options.getOption:
const series0 = context.panel.data.series[0]
const series0values = series0?.fields[1].values
const valueTemperature = series0values.get(series0values.length - 1)

const gaugeLineWidth = 7

if (valueTemperature >= 30) { gaugeColor = "red" }
else if (valueTemperature >= 26 && valueTemperature < 30) { gaugeColor = "yellow" }
else { gaugeColor = "aqua" }

option = {
  series: [
    {
      type: 'gauge',
      min: 0,
      max: 45,
      splitNumber: 5,
      progress: { show: true, width: gaugeLineWidth, },
      itemStyle: { color: gaugeColor, },
      axisLine: {
        lineStyle: {
          width: gaugeLineWidth
          // color: gaugeColor
        }
      },
      axisTick: {
        show: false
      },
      splitLine: {
        length: 10,
        lineStyle: {
          width: 2,
          color: gaugeColor
        }
      },
      axisLabel: {
        distance: 25,
        color: gaugeColor,
        fontSize: 10
      },
      anchor: {
        show: false,
        showAbove: true,
        color: gaugeColor,
        size: 15,
        itemStyle: {
          borderWidth: 5
        }
      },
      title: {
        show: false
      },
      detail: {
        valueAnimation: true,
        color: gaugeColor,
        fontSize: 20,
        offsetCenter: [0, '70%']
      },
      data: [
        {
          value: valueTemperature
        }
      ]
    }
  ]
};

return option;

