options.css:
.flw-card {
  --accent: #4ade80;
  --accent-hi: #86efac;
  --bg-1: #0b0f16;
  --bg-2: #151b26;
  --text: #e9edf4;
  --muted: #8892a6;
  --line: rgba(255, 255, 255, 0.07);

  position: relative;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  min-height: 450px;
  padding: 20px 22px 18px;
  border-radius: 18px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 16px;
  color: var(--text);
  font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: linear-gradient(160deg, var(--bg-2) 0%, var(--bg-1) 100%);
  border: 1px solid var(--line);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  animation: flw-enter 0.9s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.flw-card > *:not(.flw-bg) { position: relative; z-index: 1; }

.flw-bg {
  position: absolute;
  inset: -40%;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 50% 50%, var(--accent) 0%, transparent 30%),
    radial-gradient(circle at 15% 20%, var(--accent) 0%, transparent 22%);
  opacity: 0.1;
  filter: blur(40px);
  transition: background 1s ease;
  animation: flw-drift 24s ease-in-out infinite alternate;
}

/* Header + switch */
.flw-header { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.flw-title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
}
.flw-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
  animation: flw-pulse 2.6s ease-out infinite;
  transition: background 0.8s ease;
}
.flw-card.is-stale .flw-dot { background: #5a6273; animation: none; }

.flw-switch {
  position: relative;
  display: inline-flex;
  padding: 3px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
}
.flw-switch-pill {
  position: absolute;
  top: 3px;
  left: 3px;
  width: calc(50% - 3px);
  height: calc(100% - 6px);
  border-radius: 999px;
  background: color-mix(in srgb, var(--src) 22%, transparent);
  border: 1px solid color-mix(in srgb, var(--src) 45%, transparent);
  box-shadow: 0 0 14px -4px var(--src);
  transition: transform 0.55s cubic-bezier(0.2, 0.8, 0.2, 1), background 0.8s ease, border-color 0.8s ease;
}
.flw-card { --src: #fbbf24; }
.flw-card[data-mode="psu"] { --src: #38bdf8; }
.flw-card[data-mode="psu"] .flw-switch-pill { transform: translateX(100%); }
.flw-opt {
  position: relative;
  z-index: 1;
  flex: 1 1 0;
  min-width: 78px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 5px 12px;
  border: 0;
  background: none;
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--muted);
  transition: color 0.4s ease;
}
.flw-opt:hover { color: #c3cad8; }
.flw-opt.is-active { color: var(--text); }
.flw-opt svg {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* Banner */
.flw-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  flex-wrap: wrap;
}
.flw-state {
  font-size: 26px;
  font-weight: 400;
  letter-spacing: -0.01em;
  color: var(--accent-hi);
  transition: color 0.8s ease;
}
.flw-route {
  margin-top: 4px;
  font-size: 12.5px;
  color: var(--muted);
  letter-spacing: 0.02em;
}
.flw-route b { color: var(--text); font-weight: 500; }
.flw-route .arr { color: var(--accent); margin: 0 3px; transition: color 0.8s ease; }
.flw-swap { animation: flw-swap 0.6s cubic-bezier(0.2, 0.8, 0.2, 1); }

.flw-time {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 500;
  padding: 5px 11px 5px 9px;
  border-radius: 999px;
  color: var(--accent-hi);
  background: color-mix(in srgb, var(--accent) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--accent) 25%, transparent);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  transition: color 0.8s ease, background 0.8s ease, border-color 0.8s ease;
}
.flw-time svg {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* Diagram */
.flw-diagram { flex: 1 1 auto; min-height: 220px; display: flex; }
.flw-svg { width: 100%; height: 100%; overflow: visible; }

.flw-node { --c: #64748b; transition: opacity 0.6s ease; }
.flw-node-box {
  fill: rgba(255, 255, 255, 0.035);
  stroke: rgba(255, 255, 255, 0.1);
  stroke-width: 1.2;
  transition: stroke 0.8s ease, filter 0.8s ease;
}
.flw-node.is-active .flw-node-box {
  stroke: var(--c);
  filter: drop-shadow(0 0 10px color-mix(in srgb, var(--c) 40%, transparent));
}
.flw-node.is-off { opacity: 0.5; }
.flw-card[data-state="charging"] #flw-node-tp .flw-node-box { animation: flw-breathe 2.8s ease-in-out infinite; }

.flw-ico {
  fill: none;
  stroke: var(--c);
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: stroke 0.8s ease;
}
.flw-ico-fill { fill: var(--c); stroke: none; transition: width 1.2s cubic-bezier(0.2, 0.8, 0.2, 1), fill 0.8s ease; }
.flw-card[data-mode="psu"] .flw-ico-solar { display: none; }
.flw-card[data-mode="solar"] .flw-ico-psu { display: none; }

.flw-label {
  fill: var(--muted);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  font-family: inherit;
}
.flw-value {
  fill: var(--text);
  font-size: 26px;
  font-weight: 300;
  letter-spacing: -0.02em;
  font-family: inherit;
  font-variant-numeric: tabular-nums;
}
.flw-value--sm { font-size: 19px; font-weight: 400; }
.flw-value .u { fill: var(--muted); font-size: 14px; font-weight: 500; }
.flw-sub {
  fill: var(--c);
  font-size: 12px;
  font-weight: 500;
  font-family: inherit;
  transition: fill 0.8s ease;
}

.flw-link { --c: #64748b; }
.flw-track { fill: none; stroke: rgba(255, 255, 255, 0.07); stroke-width: 3; stroke-linecap: round; }
.flw-wire {
  fill: none;
  stroke: var(--c);
  stroke-width: 2.5;
  stroke-linecap: round;
  opacity: 0;
  transition: opacity 0.8s ease, stroke 0.8s ease;
}
.flw-dash {
  fill: none;
  stroke: var(--c);
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-dasharray: 2 14;
  opacity: 0;
  animation: flw-dash 1.1s linear infinite;
  transition: opacity 0.8s ease, stroke 0.8s ease;
}
.flw-link.is-reverse .flw-dash { animation-direction: reverse; }
.flw-link.is-active .flw-wire { opacity: 0.35; filter: drop-shadow(0 0 4px var(--c)); }
.flw-link.is-active .flw-dash { opacity: 0.9; }
.flw-particle {
  fill: #ffffff;
  opacity: 0;
  filter: drop-shadow(0 0 4px var(--c));
  transition: opacity 0.6s ease;
}
.flw-link.is-active .flw-particle { opacity: 0.95; }

.flw-cut { opacity: 0; transition: opacity 0.6s ease; }
.flw-card.src-off .flw-cut { opacity: 1; }
.flw-cut circle { fill: var(--bg-1); stroke: #f87171; stroke-width: 1.5; }
.flw-cut path { fill: none; stroke: #f87171; stroke-width: 1.8; stroke-linecap: round; }

/* Stats */
.flw-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-top: 1px solid var(--line);
  padding-top: 14px;
}
.flw-stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 0 10px;
  border-left: 1px solid var(--line);
  min-width: 0;
}
.flw-stat:first-child { border-left: none; padding-left: 0; }
.flw-stat-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
}
.flw-stat-value { font-size: 15px; font-weight: 500; font-variant-numeric: tabular-nums; white-space: nowrap; }
.flw-stat-value small { font-size: 11px; color: var(--muted); margin-left: 2px; }

/* Mode switch transition */
.flw-card.is-switching .flw-banner  { animation: flw-swap 0.6s cubic-bezier(0.2, 0.8, 0.2, 1) both; }
.flw-card.is-switching .flw-diagram { animation: flw-swap 0.6s cubic-bezier(0.2, 0.8, 0.2, 1) 0.08s both; }
.flw-card.is-switching .flw-stats   { animation: flw-swap 0.6s cubic-bezier(0.2, 0.8, 0.2, 1) 0.16s both; }

/* Animations */
@keyframes flw-enter {
  from { opacity: 0; transform: translateY(10px) scale(0.99); }
  to   { opacity: 1; transform: none; }
}
@keyframes flw-drift {
  from { transform: translate(0, 0) rotate(0deg); }
  to   { transform: translate(5%, -4%) rotate(8deg); }
}
@keyframes flw-pulse {
  0%   { box-shadow: 0 0 0 0 var(--accent); }
  70%  { box-shadow: 0 0 0 8px transparent; }
  100% { box-shadow: 0 0 0 0 transparent; }
}
@keyframes flw-dash { to { stroke-dashoffset: -16; } }
@keyframes flw-breathe {
  0%, 100% { filter: drop-shadow(0 0 6px color-mix(in srgb, var(--c) 30%, transparent)); }
  50%      { filter: drop-shadow(0 0 16px color-mix(in srgb, var(--c) 60%, transparent)); }
}
@keyframes flw-swap {
  from { opacity: 0; transform: translateY(6px); }
  to   { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .flw-card, .flw-card * { animation: none !important; transition: none !important; }
}

options.onInit:
// Sets the text from customProperties
const htmlgraphicsText = htmlNode.getElementById('htmlgraphics-text');

if (htmlgraphicsText) {
  htmlgraphicsText.textContent = customProperties.text;

  // Change the text color based on the theme
  if (theme.isDark) {
    htmlgraphicsText.style.color = 'green';
  } else {
    htmlgraphicsText.style.color = 'red';
  }
}

options.onRender:
const card = htmlNode.querySelector('.flw-card');
if (!card) return;
const $ = (id) => htmlNode.querySelector('#' + id);
const STORE_KEY = 'pwr-card-mode';      // shared with the Power Input card
const st = card.__flw || (card.__flw = { mode: null, bound: false, state: null });

if (!st.mode) {
  let m = 'solar';
  try { m = localStorage.getItem(STORE_KEY) || 'solar'; } catch (e) {}
  st.mode = m === 'psu' ? 'psu' : 'solar';
}

/* ---------- Settings ---------- */
const FIELD_SOURCE = 'Voltage1';         // part of the field name for the source
const FIELD_BATTERY = 'Voltage2';        // part of the field name for the battery
const SOURCE_ON = { solar: 4.0, psu: 4.5 };  // source considered present above this (V)
const BAT_EMPTY = 3.0;
const BAT_MAX = 4.135;
const RECHARGE_V = 4.06;                 // CN3065 restarts charging below this
const BAT_LOW = 3.3;
const CHARGE_SLOPE = 8;                  // mV/h rise that counts as charging
const SLOPE_WINDOW_MS = 20 * 60 * 1000;
const STALE_MS = 5 * 60 * 1000;
const LOCALE = 'en-US';
const COLORS = {
  solar: '#fbbf24',
  psu: '#38bdf8',
  charge: '#4ade80',
  battery: '#fb923c',
  low: '#f87171'
};

/* ---------- Helpers ---------- */
const toArr = (v) => {
  if (!v) return [];
  if (Array.isArray(v)) return v;
  if (typeof v.toArray === 'function') return v.toArray();
  if (typeof v.get === 'function') { const a = []; for (let i = 0; i < v.length; i++) a.push(v.get(i)); return a; }
  return Array.from(v);
};
const hexToRgb = (c) => [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16));
const rgbToHex = (a) => '#' + a.map((v) => Math.round(v).toString(16).padStart(2, '0')).join('');
const mix = (c1, c2, k) => { const a = hexToRgb(c1), b = hexToRgb(c2); return rgbToHex(a.map((v, j) => v + (b[j] - v) * k)); };
const fmt2 = (v) => v.toLocaleString(LOCALE, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const fmtTime = (t) => new Date(t).toLocaleTimeString(LOCALE, { hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
const fmtDur = (ms) => {
  const m = Math.max(0, Math.round(ms / 60000));
  const d = Math.floor(m / 1440), h = Math.floor((m % 1440) / 60), mm = m % 60;
  if (d > 0) return `${d}d ${h}h`;
  if (h > 0) return `${h}h ${String(mm).padStart(2, '0')}m`;
  return `${mm}m`;
};
const regress = (pts) => {
  const t0 = pts[0].t;
  let sx = 0, sy = 0, sxx = 0, sxy = 0;
  pts.forEach((p) => {
    const x = (p.t - t0) / 3.6e6, y = p.v * 1000;
    sx += x; sy += y; sxx += x * x; sxy += x * y;
  });
  const n = pts.length, den = n * sxx - sx * sx;
  return den ? (n * sxy - sx * sy) / den : 0;
};

/* ---------- Data: find source and battery fields ---------- */
const metrics = [];
for (const s of (data && data.series) || []) {
  const tf = s.fields.find((f) => f.type === 'time');
  const ts = tf ? toArr(tf.values) : [];
  s.fields.forEach((f) => {
    if (f === tf || f.type === 'string') return;
    const name = [s.name, s.refId, f.name, f.config && f.config.displayName, f.config && f.config.displayNameFromDS, JSON.stringify(f.labels || {})].join(' ');
    const pts = [];
    toArr(f.values).forEach((v, i) => {
      if (v === null || v === undefined || v === '') return;
      const n = Number(v);
      if (isNaN(n)) return;
      pts.push({ t: ts[i] != null ? Number(ts[i]) : i * 60000, v: n });
    });
    metrics.push({ name, pts });
  });
}
let srcM = metrics.find((m) => m.name.includes(FIELD_SOURCE));
let batM = metrics.find((m) => m.name.includes(FIELD_BATTERY));
if (!srcM || !batM) { srcM = srcM || metrics[0]; batM = batM || metrics[1]; }

const srcPts = srcM ? srcM.pts.filter((p) => p.v >= 0 && p.v < 15).sort((a, b) => a.t - b.t) : [];
const batPts = batM ? batM.pts.filter((p) => p.v > 2.5 && p.v < 5).sort((a, b) => a.t - b.t) : [];

/* ---------- Switch (bound once, synced with other cards) ---------- */
if (!st.bound) {
  const apply = (m) => {
    if (m !== 'solar' && m !== 'psu') return;
    if (m === st.mode) return;
    st.mode = m;
    st.state = null;
    card.classList.remove('is-switching');
    void card.offsetWidth;
    card.classList.add('is-switching');
    if (st.paint) st.paint();
  };
  htmlNode.querySelectorAll('.flw-opt').forEach((btn) => {
    btn.addEventListener('click', () => {
      const m = btn.dataset.mode;
      try { localStorage.setItem(STORE_KEY, m); } catch (e) {}
      apply(m);
      window.dispatchEvent(new CustomEvent('pwr-mode-change', { detail: m }));
    });
  });
  window.addEventListener('pwr-mode-change', (e) => {
    if (card.isConnected) apply(e.detail);
  });
  st.bound = true;
}

if (!srcPts.length || !batPts.length) {
  card.dataset.mode = st.mode;
  $('flw-state').textContent = 'No data in range';
  $('flw-route').textContent = !srcPts.length ? 'Source voltage not found' : 'Battery voltage not found';
  card.classList.add('is-stale');
  st.paint = null;
  return;
}

/* ---------- Battery slope at every point (mV/h) ---------- */
const batSlope = batPts.map((p, i) => {
  let j = i;
  while (j > 0 && p.t - batPts[j - 1].t <= SLOPE_WINDOW_MS) j--;
  const win = batPts.slice(j, i + 1);
  return win.length >= 3 ? regress(win) : 0;
});

const stateOf = (s, b, slope, mode) => {
  if (s < SOURCE_ON[mode]) return 'battery';
  if (slope > CHARGE_SLOPE) return 'charging';
  if (b >= RECHARGE_V) return 'full';
  return 'charging';
};

/* Time spent in the current state */
const merged = [
  ...srcPts.map((p) => ({ t: p.t, k: 's', v: p.v })),
  ...batPts.map((p, i) => ({ t: p.t, k: 'b', v: p.v, sl: batSlope[i] }))
].sort((a, b) => a.t - b.t);

const stateDuration = (mode) => {
  let s = null, b = null, sl = 0, prev = null, changeT = null, firstT = null, lastT = null;
  for (const e of merged) {
    if (e.k === 's') s = e.v; else { b = e.v; sl = e.sl; }
    if (s === null || b === null) continue;
    const stt = stateOf(s, b, sl, mode);
    if (firstT === null) firstT = e.t;
    if (stt !== prev) { if (prev !== null) changeT = e.t; prev = stt; }
    lastT = e.t;
  }
  return { ms: (lastT ?? 0) - (changeT ?? firstT ?? 0), atLeast: changeT === null };
};

/* ---------- Current values ---------- */
const lastS = srcPts[srcPts.length - 1];
const lastB = batPts[batPts.length - 1];
const src = lastS.v;
const bat = lastB.v;
const slopeNow = batSlope[batSlope.length - 1];
const pct = Math.max(0, Math.min(100, ((bat - BAT_EMPTY) / (BAT_MAX - BAT_EMPTY)) * 100));
const lastT = Math.max(lastS.t, lastB.t);
card.classList.toggle('is-stale', Date.now() - lastT > STALE_MS);

/* ---------- Paint (refresh and mode switch) ---------- */
const setLink = (id, active, color, reverse) => {
  const g = $(id);
  g.style.setProperty('--c', color);
  g.classList.toggle('is-active', active);
  g.classList.toggle('is-reverse', reverse);
  g.querySelectorAll('animateMotion').forEach((a) => a.setAttribute('keyPoints', reverse ? '1;0' : '0;1'));
};
const setNode = (id, color, active, off) => {
  const g = $(id);
  g.style.setProperty('--c', color);
  g.classList.toggle('is-active', active);
  g.classList.toggle('is-off', !!off);
};

const paint = () => {
  const mode = st.mode;
  const isSolar = mode === 'solar';
  const srcName = isSolar ? 'Solar' : 'PSU';
  const srcColor = isSolar ? COLORS.solar : COLORS.psu;
  const srcOn = src >= SOURCE_ON[mode];
  const state = stateOf(src, bat, slopeNow, mode);
  const low = bat < BAT_LOW;
  const batColor = low ? COLORS.low : COLORS.battery;

  card.dataset.mode = mode;
  card.dataset.state = state;
  card.classList.toggle('src-off', !srcOn);
  htmlNode.querySelectorAll('.flw-opt').forEach((b) => b.classList.toggle('is-active', b.dataset.mode === mode));

  const accent = state === 'charging' ? COLORS.charge : state === 'full' ? srcColor : batColor;
  card.style.setProperty('--accent', accent);
  card.style.setProperty('--accent-hi', mix(accent, '#ffffff', 0.35));

  /* Banner */
  const arr = '<span class="arr">&rarr;</span>';
  let title, route;
  if (state === 'charging') {
    title = 'Charging';
    route = `<b>${srcName}</b>${arr}CN3065${arr}<b>ESP32</b> + <b>Battery</b>`;
  } else if (state === 'full') {
    title = `Powered by ${srcName}`;
    route = `<b>${srcName}</b>${arr}CN3065${arr}<b>ESP32</b> &middot; Battery full`;
  } else {
    title = low ? 'Battery low' : 'On battery';
    route = `<b>Battery</b>${arr}CN3065${arr}<b>ESP32</b> &middot; ${srcName} offline`;
  }
  const stateEl = $('flw-state');
  const key = state + mode + low;
  if (st.state !== key) {
    stateEl.classList.remove('flw-swap');
    void stateEl.offsetWidth;
    stateEl.classList.add('flw-swap');
    st.state = key;
  }
  stateEl.textContent = title;
  $('flw-route').innerHTML = route;

  const dur = stateDuration(mode);
  $('flw-time-v').textContent = (dur.atLeast ? 'for over ' : 'for ') + fmtDur(dur.ms);

  /* Links */
  setLink('flw-link-src', srcOn, srcColor, false);
  setLink('flw-link-bat', state !== 'full', state === 'charging' ? COLORS.charge : batColor, state === 'charging');
  setLink('flw-link-load', true, srcOn ? srcColor : batColor, false);

  /* Nodes */
  setNode('flw-node-src', srcOn ? srcColor : COLORS.low, srcOn, !srcOn);
  $('flw-src-label').textContent = srcName.toUpperCase();
  $('flw-src-v').textContent = fmt2(src);
  $('flw-src-sub').textContent = srcOn ? 'Active' : 'Offline';

  const batNodeColor = state === 'battery' ? batColor : COLORS.charge;
  setNode('flw-node-bat', batNodeColor, true, false);
  $('flw-bat-v').textContent = fmt2(bat);
  $('flw-bat-sub').textContent = `${Math.round(pct)}% · ${state === 'charging' ? 'Charging' : state === 'full' ? 'Full' : 'Discharging'}`;
  $('flw-bat-fill').setAttribute('width', Math.max(1, 18 * pct / 100).toFixed(2));

  setNode('flw-node-tp', state === 'charging' ? COLORS.charge : state === 'full' ? srcColor : batColor, true, false);
  $('flw-tp-sub').textContent = state === 'charging' ? 'Charging' : state === 'full' ? 'Charge complete' : 'Battery mode';

  const loadColor = srcOn ? srcColor : batColor;
  setNode('flw-node-esp', loadColor, true, false);
  $('flw-esp-v').textContent = `via ${state === 'battery' ? 'Battery' : srcName}`;
  $('flw-esp-sub').textContent = card.classList.contains('is-stale') ? 'No recent data' : 'Running';

  /* Stats */
  $('flw-s1-l').textContent = srcName;
  $('flw-s1-v').innerHTML = fmt2(src) + '<small>V</small>';
  $('flw-s2-v').innerHTML = fmt2(bat) + '<small>V</small>';
  $('flw-s3-v').innerHTML = Math.round(pct) + '<small>%</small>';
  $('flw-s4-v').textContent = fmtTime(lastT);
};

st.paint = paint;
paint();

options.css:
.tmp-wrap {
  container-type: inline-size;
  width: 100%;
  height: 100%;
}

.tmp-card {
  --accent: #4ade80;
  --bg-1: #0b0f16;
  --bg-2: #151b26;
  --text: #e9edf4;
  --muted: #8892a6;
  --line: rgba(255, 255, 255, 0.07);

  position: relative;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  min-height: 190px;
  padding: 16px 20px 14px;
  border-radius: 18px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 12px;
  color: var(--text);
  font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: linear-gradient(160deg, var(--bg-2) 0%, var(--bg-1) 100%);
  border: 1px solid var(--line);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  animation: tmp-enter 0.9s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.tmp-card > *:not(.tmp-bg) { position: relative; z-index: 1; }

.tmp-bg {
  position: absolute;
  inset: -50%;
  z-index: 0;
  pointer-events: none;
  background: radial-gradient(circle at 22% 45%, var(--accent) 0%, transparent 30%);
  opacity: 0.12;
  filter: blur(40px);
  transition: background 1s ease;
  animation: tmp-drift 22s ease-in-out infinite alternate;
}

/* Header */
.tmp-header { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.tmp-title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}
.tmp-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
  animation: tmp-pulse 2.6s ease-out infinite;
  transition: background 0.8s ease;
}
.tmp-card.is-stale .tmp-dot { background: #5a6273; animation: none; }
.tmp-meta { display: flex; align-items: center; gap: 10px; }
.tmp-updated { font-size: 11px; color: var(--muted); font-variant-numeric: tabular-nums; }
.tmp-badge {
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.04em;
  padding: 4px 10px;
  border-radius: 999px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
}

/* Body */
.tmp-body {
  flex: 1 1 auto;
  min-height: 0;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 24px;
}
.tmp-left { display: flex; align-items: center; gap: 14px; }

/* Thermometer */
.tmp-thermo { width: 40px; height: 120px; flex: 0 0 auto; overflow: visible; }
.tmp-glass {
  fill: rgba(255, 255, 255, 0.03);
  stroke: rgba(255, 255, 255, 0.2);
  stroke-width: 1.8;
}
.tmp-track { fill: rgba(255, 255, 255, 0.04); }
.tmp-mercury {
  transform: translateY(90px);
  transition: transform 1.8s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.tmp-merc-a { stop-color: var(--accent); stop-opacity: 0.7; transition: stop-color 1s ease; }
.tmp-merc-b { stop-color: var(--accent); stop-opacity: 1; transition: stop-color 1s ease; }
.tmp-bulb-glow {
  fill: var(--accent);
  opacity: 0.25;
  filter: blur(6px);
  animation: tmp-glow 3.6s ease-in-out infinite;
  transition: fill 1s ease;
}
.tmp-shine { stroke: rgba(255, 255, 255, 0.22); stroke-width: 1.2; stroke-linecap: round; fill: none; }
.tmp-ticks line { stroke: rgba(255, 255, 255, 0.22); stroke-width: 1.2; stroke-linecap: round; }
.tmp-ticks line.minor { stroke: rgba(255, 255, 255, 0.12); }

/* Reading */
.tmp-reading { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.tmp-value { display: flex; align-items: flex-start; gap: 4px; line-height: 1; }
#tmp-value {
  font-size: 46px;
  font-weight: 300;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
  background: linear-gradient(180deg, #ffffff 0%, #c9d1df 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.tmp-unit { font-size: 18px; font-weight: 500; color: var(--muted); margin-top: 4px; }
.tmp-level { font-size: 14px; font-weight: 500; color: var(--accent); transition: color 0.8s ease; white-space: nowrap; }
.tmp-swap { animation: tmp-swap 0.6s cubic-bezier(0.2, 0.8, 0.2, 1); }

.tmp-trend {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: fit-content;
  white-space: nowrap;
  font-size: 12px;
  font-weight: 500;
  padding: 4px 10px 4px 8px;
  border-radius: 999px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
  transition: color 0.5s ease, background 0.5s ease;
}
.tmp-trend svg {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.tmp-trend--up { color: #fb923c; background: rgba(251, 146, 60, 0.08); }
.tmp-trend--down { color: #38bdf8; background: rgba(56, 189, 248, 0.08); }

/* Chart */
.tmp-right { display: flex; flex-direction: column; gap: 6px; min-width: 0; min-height: 0; }
.tmp-chips { display: flex; justify-content: flex-end; gap: 6px; flex-wrap: wrap; }
.tmp-chip {
  font-size: 11px;
  padding: 3px 9px;
  border-radius: 999px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--line);
  font-variant-numeric: tabular-nums;
}
.tmp-chip b { color: var(--text); font-weight: 600; margin-left: 4px; }

.tmp-svg { flex: 1 1 auto; width: 100%; min-height: 80px; overflow: visible; }
.tmp-grid line { stroke: var(--line); stroke-width: 1; }
.tmp-grid text {
  fill: var(--muted);
  font-size: 9.5px;
  font-family: inherit;
  font-variant-numeric: tabular-nums;
}
.tmp-line {
  fill: none;
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 0 6px var(--accent));
}
.tmp-area { opacity: 0; transition: opacity 1.2s ease 0.4s; }
.tmp-area.is-visible { opacity: 1; }
.tmp-area-a { stop-color: var(--accent); stop-opacity: 0.22; transition: stop-color 1s ease; }
.tmp-area-b { stop-color: var(--accent); stop-opacity: 0; }

.tmp-marks circle { fill: var(--bg-1); stroke-width: 1.6; }
.tmp-marks text {
  font-size: 10px;
  font-weight: 600;
  font-family: inherit;
  text-anchor: middle;
  font-variant-numeric: tabular-nums;
}
.tmp-marks { animation: tmp-fade 1s ease 1.4s both; }

.tmp-pt { fill: #ffffff; }
.tmp-ring {
  fill: none;
  stroke: var(--accent);
  stroke-width: 1.5;
  transform-box: fill-box;
  transform-origin: center;
  animation: tmp-ring 2.4s ease-out infinite;
}

.tmp-xaxis {
  display: flex;
  justify-content: space-between;
  padding-left: 30px;
  font-size: 10px;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

/* Narrow panels: stack */
@container (max-width: 560px) {
  .tmp-body { grid-template-columns: 1fr; gap: 14px; }
  .tmp-chips { justify-content: flex-start; }
}

/* Animations */
@keyframes tmp-enter {
  from { opacity: 0; transform: translateY(10px) scale(0.99); }
  to   { opacity: 1; transform: none; }
}
@keyframes tmp-drift {
  from { transform: translate(0, 0); }
  to   { transform: translate(6%, -5%); }
}
@keyframes tmp-pulse {
  0%   { box-shadow: 0 0 0 0 var(--accent); }
  70%  { box-shadow: 0 0 0 8px transparent; }
  100% { box-shadow: 0 0 0 0 transparent; }
}
@keyframes tmp-glow { 0%, 100% { opacity: 0.18; } 50% { opacity: 0.38; } }
@keyframes tmp-ring {
  0%   { transform: scale(1);   opacity: 0.9; }
  100% { transform: scale(3.2); opacity: 0; }
}
@keyframes tmp-swap {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: none; }
}
@keyframes tmp-fade { from { opacity: 0; } to { opacity: 1; } }

@media (prefers-reduced-motion: reduce) {
  .tmp-card, .tmp-card * { animation: none !important; transition: none !important; }
}

options.onInit:
// Sets the text from customProperties
const htmlgraphicsText = htmlNode.getElementById('htmlgraphics-text');

if (htmlgraphicsText) {
  htmlgraphicsText.textContent = customProperties.text;

  // Change the text color based on the theme
  if (theme.isDark) {
    htmlgraphicsText.style.color = 'green';
  } else {
    htmlgraphicsText.style.color = 'red';
  }
}

options.onRender:
const card = htmlNode.querySelector('.tmp-card');
if (!card) return;
const $ = (id) => htmlNode.querySelector('#' + id);
const st = card.__tmp || (card.__tmp = { num: null, raf: null, drawn: false, level: null, init: false });

/* ---------- Settings ---------- */
const TUBE_MIN = 0;                      // thermometer scale (°C)
const TUBE_MAX = 40;
const RATE_WINDOW_MS = 30 * 60 * 1000;   // window used for the trend
const RATE_THRESHOLD = 0.3;              // °C/h needed to leave "Stable"
const STALE_MS = 5 * 60 * 1000;
const MAX_POINTS = 240;
const LOCALE = 'en-US';
const PALETTE = [
  [0, '#60a5fa'], [10, '#38bdf8'], [18, '#2dd4bf'], [22, '#4ade80'],
  [26, '#facc15'], [30, '#fb923c'], [35, '#f87171'], [40, '#ef4444']
];
const LEVELS = [
  { max: 0,        label: 'Freezing' },
  { max: 10,       label: 'Cold' },
  { max: 18,       label: 'Cool' },
  { max: 24,       label: 'Comfortable' },
  { max: 28,       label: 'Warm' },
  { max: 33,       label: 'Hot' },
  { max: Infinity, label: 'Very hot' }
];

/* ---------- Helpers ---------- */
const toArr = (v) => {
  if (!v) return [];
  if (Array.isArray(v)) return v;
  if (typeof v.toArray === 'function') return v.toArray();
  if (typeof v.get === 'function') { const a = []; for (let i = 0; i < v.length; i++) a.push(v.get(i)); return a; }
  return Array.from(v);
};
const hexToRgb = (c) => [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16));
const colorAt = (t) => {
  if (t <= PALETTE[0][0]) return PALETTE[0][1];
  for (let i = 1; i < PALETTE.length; i++) {
    const [t1, c1] = PALETTE[i];
    if (t <= t1) {
      const [t0, c0] = PALETTE[i - 1];
      const k = (t - t0) / (t1 - t0);
      const a = hexToRgb(c0), b = hexToRgb(c1);
      return '#' + a.map((v, j) => Math.round(v + (b[j] - v) * k).toString(16).padStart(2, '0')).join('');
    }
  }
  return PALETTE[PALETTE.length - 1][1];
};
const fmt = (v) => v.toLocaleString(LOCALE, { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const fmtTime = (t) => new Date(t).toLocaleTimeString(LOCALE, { hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });

/* ---------- Data ---------- */
let points = [];
let hasTime = false;
for (const s of (data && data.series) || []) {
  const tf = s.fields.find((f) => f.type === 'time');
  const vf = s.fields.find((f) => f.type === 'number');
  if (!vf) continue;
  hasTime = !!tf;
  const ts = tf ? toArr(tf.values) : [];
  toArr(vf.values).forEach((v, i) => {
    if (v !== null && v !== undefined && !isNaN(v)) {
      points.push({ t: ts[i] != null ? Number(ts[i]) : i * 60000, v: Number(v) });
    }
  });
  break;
}
points.sort((a, b) => a.t - b.t);

if (!points.length) {
  $('tmp-value').textContent = '--';
  $('tmp-level').textContent = 'No data in range';
  $('tmp-trend').innerHTML = '';
  card.classList.add('is-stale');
  return;
}

/* ---------- Calculations ---------- */
const temps = points.map((p) => p.v);
const last = points[points.length - 1];
const cur = last.v;
const tMin = Math.min(...temps);
const tMax = Math.max(...temps);
const tAvg = temps.reduce((a, b) => a + b, 0) / temps.length;
const level = LEVELS.find((l) => cur < l.max);
const accent = colorAt(cur);

const win = points.filter((p) => p.t >= last.t - RATE_WINDOW_MS);
let rate = 0;
if (win.length >= 3) {
  const t0 = win[0].t;
  let sx = 0, sy = 0, sxx = 0, sxy = 0;
  win.forEach((p) => {
    const x = (p.t - t0) / 3.6e6;
    sx += x; sy += p.v; sxx += x * x; sxy += x * p.v;
  });
  const n = win.length;
  const den = n * sxx - sx * sx;
  if (den) rate = (n * sxy - sx * sy) / den;
}
const trend = rate > RATE_THRESHOLD ? 'up' : rate < -RATE_THRESHOLD ? 'down' : 'flat';

/* ---------- Theme and state ---------- */
card.style.setProperty('--accent', accent);
card.classList.toggle('is-stale', hasTime && Date.now() - last.t > STALE_MS);

/* ---------- Animated value ---------- */
const valEl = $('tmp-value');
if (st.num !== cur) {
  const from = st.num ?? TUBE_MIN;
  cancelAnimationFrame(st.raf);
  const t0 = performance.now();
  const dur = 1200;
  const step = (now) => {
    const k = Math.min(1, (now - t0) / dur);
    const e = 1 - Math.pow(1 - k, 3);
    valEl.textContent = fmt(from + (cur - from) * e);
    if (k < 1) st.raf = requestAnimationFrame(step);
  };
  st.raf = requestAnimationFrame(step);
  st.num = cur;
}

/* ---------- Thermometer ---------- */
const merc = $('tmp-mercury');
if (!st.init) { merc.getBoundingClientRect(); st.init = true; }
const ratio = Math.max(0, Math.min(1, (cur - TUBE_MIN) / (TUBE_MAX - TUBE_MIN)));
merc.style.transform = `translateY(${(90 - ratio * 80).toFixed(2)}px)`;

/* ---------- Level ---------- */
const lvlEl = $('tmp-level');
if (st.level !== level.label) {
  lvlEl.textContent = level.label;
  lvlEl.classList.remove('tmp-swap');
  void lvlEl.offsetWidth;
  lvlEl.classList.add('tmp-swap');
  st.level = level.label;
}

/* ---------- Trend ---------- */
const ICONS = {
  up:   '<svg viewBox="0 0 16 16"><path d="M4 10l4-4 4 4"/></svg>',
  down: '<svg viewBox="0 0 16 16"><path d="M4 6l4 4 4-4"/></svg>',
  flat: '<svg viewBox="0 0 16 16"><path d="M3 8h10"/></svg>'
};
const rateTxt = Math.abs(rate).toFixed(1) + ' °C/h';
const TEXT = { up: 'Rising +' + rateTxt, down: 'Falling -' + rateTxt, flat: 'Stable' };
const trendEl = $('tmp-trend');
trendEl.className = 'tmp-trend tmp-trend--' + trend;
trendEl.innerHTML = ICONS[trend] + '<span>' + TEXT[trend] + '</span>';

/* ---------- Chips and header ---------- */
$('tmp-min').textContent = fmt(tMin) + '°';
$('tmp-avg').textContent = fmt(tAvg) + '°';
$('tmp-max').textContent = fmt(tMax) + '°';
$('tmp-updated').textContent = hasTime ? 'Updated ' + fmtTime(last.t) : '';

/* ---------- Chart ---------- */
const recent = points.slice(-MAX_POINTS);
const vals = recent.map((p) => p.v);

const svg = $('tmp-svg');
const w = Math.max(80, svg.clientWidth || 300);
const h = Math.max(60, svg.clientHeight || 100);
svg.setAttribute('viewBox', `0 0 ${w} ${h}`);

let lo = Math.min(...vals), hi = Math.max(...vals);
if (hi - lo < 1) { const mid = (hi + lo) / 2; lo = mid - 0.5; hi = mid + 0.5; }
const padV = (hi - lo) * 0.15;
lo -= padV; hi += padV;

const padL = 30, padR = 6, padT = 16, padB = 16;
const xOf = (i) => vals.length === 1 ? (padL + w) / 2 : padL + (i * (w - padL - padR)) / (vals.length - 1);
const yOf = (v) => h - padB - ((v - lo) / (hi - lo)) * (h - padT - padB);

/* Grid with nice ticks */
const rawStep = (hi - lo) / 3;
const step = [0.1, 0.2, 0.5, 1, 2, 5, 10].find((s) => s >= rawStep) || 10;
const dec = step < 1 ? 1 : 0;
let grid = '';
for (let v = Math.ceil(lo / step) * step; v <= hi + 1e-9; v += step) {
  const y = yOf(v).toFixed(1);
  grid += `<line x1="${padL}" x2="${w - padR}" y1="${y}" y2="${y}"/>`;
  grid += `<text x="0" y="${(Number(y) + 3).toFixed(1)}">${v.toFixed(dec)}°</text>`;
}
$('tmp-grid').innerHTML = grid;

/* Temperature-colored line gradient */
const lg = $('tmpLineGrad');
lg.setAttribute('y1', yOf(lo).toFixed(1));
lg.setAttribute('y2', yOf(hi).toFixed(1));
let stops = '';
for (let k = 0; k <= 6; k++) {
  const t = lo + ((hi - lo) * k) / 6;
  stops += `<stop offset="${(k / 6).toFixed(3)}" stop-color="${colorAt(t)}"/>`;
}
lg.innerHTML = stops;

/* Smooth path */
const xy = vals.map((v, i) => [xOf(i), yOf(v)]);
const smooth = (P) => {
  let d = `M${P[0][0].toFixed(1)},${P[0][1].toFixed(1)}`;
  for (let i = 0; i < P.length - 1; i++) {
    const p0 = P[i - 1] || P[i], p1 = P[i], p2 = P[i + 1], p3 = P[i + 2] || p2;
    const t = 1 / 6;
    const c1x = p1[0] + (p2[0] - p0[0]) * t, c1y = p1[1] + (p2[1] - p0[1]) * t;
    const c2x = p2[0] - (p3[0] - p1[0]) * t, c2y = p2[1] - (p3[1] - p1[1]) * t;
    d += ` C${c1x.toFixed(1)},${c1y.toFixed(1)} ${c2x.toFixed(1)},${c2y.toFixed(1)} ${p2[0].toFixed(1)},${p2[1].toFixed(1)}`;
  }
  return d;
};
const lineD = smooth(xy);
const line = $('tmp-line');
const area = $('tmp-area');
line.setAttribute('d', lineD);
area.setAttribute('d', `${lineD} L${xy[xy.length - 1][0].toFixed(1)},${h - padB} L${xy[0][0].toFixed(1)},${h - padB} Z`);

const [lx, ly] = xy[xy.length - 1];
['tmp-dot', 'tmp-ring'].forEach((id) => {
  const c = $(id);
  c.setAttribute('cx', lx.toFixed(1));
  c.setAttribute('cy', ly.toFixed(1));
});

/* Min / max markers */
let marks = '';
const iMax = vals.indexOf(Math.max(...vals));
const iMin = vals.indexOf(Math.min(...vals));
if (iMax !== iMin) {
  const clampX = (x) => Math.max(padL + 14, Math.min(w - padR - 14, x));
  const [mxX, mxY] = xy[iMax];
  const [mnX, mnY] = xy[iMin];
  const cMax = colorAt(vals[iMax]);
  const cMin = colorAt(vals[iMin]);
  marks += `<circle cx="${mxX.toFixed(1)}" cy="${mxY.toFixed(1)}" r="3" stroke="${cMax}"/>`;
  marks += `<text x="${clampX(mxX).toFixed(1)}" y="${(mxY - 7).toFixed(1)}" fill="${cMax}">${fmt(vals[iMax])}°</text>`;
  marks += `<circle cx="${mnX.toFixed(1)}" cy="${mnY.toFixed(1)}" r="3" stroke="${cMin}"/>`;
  marks += `<text x="${clampX(mnX).toFixed(1)}" y="${(mnY + 14).toFixed(1)}" fill="${cMin}">${fmt(vals[iMin])}°</text>`;
}
$('tmp-marks').innerHTML = marks;

/* Draw-in animation */
if (!st.drawn) {
  const len = line.getTotalLength();
  line.style.transition = 'none';
  line.style.strokeDasharray = len;
  line.style.strokeDashoffset = len;
  line.getBoundingClientRect();
  line.style.transition = 'stroke-dashoffset 1.8s cubic-bezier(0.4, 0, 0.2, 1)';
  line.style.strokeDashoffset = '0';
  setTimeout(() => {
    line.style.transition = '';
    line.style.strokeDasharray = 'none';
  }, 1900);
  st.drawn = true;
}
area.classList.add('is-visible');

/* X axis */
if (hasTime) {
  $('tmp-x0').textContent = fmtTime(recent[0].t);
  $('tmp-x1').textContent = fmtTime(recent[Math.floor(recent.length / 2)].t);
  $('tmp-x2').textContent = fmtTime(recent[recent.length - 1].t);
} else {
  $('tmp-x0').textContent = $('tmp-x1').textContent = $('tmp-x2').textContent = '';
}

options.css:
.wfi-wrap {
  width: 100%;
  height: 100%;
}

.wfi-card {
  --accent: #4ade80;
  --accent-hi: #86efac;
  --bg-1: #0b0f16;
  --bg-2: #151b26;
  --text: #e9edf4;
  --muted: #8892a6;
  --line: rgba(255, 255, 255, 0.07);

  position: relative;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  min-height: 120px;
  padding: 12px 14px 12px;
  border-radius: 16px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 4px;
  color: var(--text);
  font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: linear-gradient(160deg, var(--bg-2) 0%, var(--bg-1) 100%);
  border: 1px solid var(--line);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  animation: wfi-enter 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.wfi-card > *:not(.wfi-bg):not(.wfi-spark) { position: relative; z-index: 1; }

.wfi-bg {
  position: absolute;
  inset: -50%;
  z-index: 0;
  pointer-events: none;
  background: radial-gradient(circle at 50% 48%, var(--accent) 0%, transparent 26%);
  opacity: 0.12;
  filter: blur(30px);
  transition: background 1s ease;
  animation: wfi-glow 5s ease-in-out infinite;
}

/* Background sparkline */
.wfi-spark {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 55%;
  z-index: 0;
  pointer-events: none;
  opacity: 0.22;
}
.wfi-spark svg { width: 100%; height: 100%; display: block; }
.wfi-spark-line {
  fill: none;
  stroke: var(--accent);
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: stroke 1s ease;
}
.wfi-spark-area { opacity: 0; transition: opacity 1.2s ease 0.3s; }
.wfi-spark-area.is-visible { opacity: 1; }
.wfi-spark-a { stop-color: var(--accent); stop-opacity: 0.18; transition: stop-color 1s ease; }
.wfi-spark-b { stop-color: var(--accent); stop-opacity: 0; }

/* Header */
.wfi-header { display: flex; align-items: center; }
.wfi-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
}
.wfi-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent);
  animation: wfi-pulse 2.6s ease-out infinite;
  transition: background 0.8s ease;
}
.wfi-card.is-stale .wfi-dot { background: #5a6273; animation: none; }

/* Center icon */
.wfi-center {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  container-type: size;
}
.wfi-icon {
  height: clamp(28px, 72cqh, 68px);
  aspect-ratio: 24 / 20;
  display: block;
  overflow: visible;
}
.wfi-arc {
  fill: none;
  stroke: rgba(255, 255, 255, 0.1);
  stroke-width: 2.2;
  stroke-linecap: round;
  transition: stroke 0.8s ease;
}
.wfi-arc.is-on {
  stroke: var(--accent);
  /* animation: wfi-wave 3.2s ease-in-out infinite;
  animation-delay: calc(var(--i) * 0.25s); */
}
.wfi-node {
  fill: var(--accent);
  transition: fill 0.8s ease;
  filter: drop-shadow(0 0 3px var(--accent));
}
.wfi-card.is-stale .wfi-arc.is-on { animation: none; opacity: 0.5; }

/* Bottom line */
.wfi-level {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
.wfi-label { color: var(--accent-hi); transition: color 0.8s ease; }
.wfi-sep { color: var(--muted); opacity: 0.6; }
.wfi-q { color: var(--muted); font-weight: 400; }
.wfi-dbm { color: var(--text); font-weight: 500; }
.wfi-dbm small { color: var(--muted); font-size: 11px; font-weight: 400; margin-left: 2px; }
.wfi-swap { animation: wfi-swap 0.6s cubic-bezier(0.2, 0.8, 0.2, 1); }

/* Animations */
@keyframes wfi-enter {
  from { opacity: 0; transform: translateY(8px) scale(0.99); }
  to   { opacity: 1; transform: none; }
}
@keyframes wfi-pulse {
  0%   { box-shadow: 0 0 0 0 var(--accent); }
  70%  { box-shadow: 0 0 0 7px transparent; }
  100% { box-shadow: 0 0 0 0 transparent; }
}
@keyframes wfi-glow { 0%, 100% { opacity: 0.1; } 50% { opacity: 0.18; } }
@keyframes wfi-wave {
  0%, 45%, 100% { opacity: 0.65; filter: none; }
  15%           { opacity: 1; filter: drop-shadow(0 0 3px var(--accent)); }
}
@keyframes wfi-swap {
  from { opacity: 0; transform: translateY(3px); }
  to   { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .wfi-card, .wfi-card * { animation: none !important; transition: none !important; }
}

options.onInit:
// Sets the text from customProperties
const htmlgraphicsText = htmlNode.getElementById('htmlgraphics-text');

if (htmlgraphicsText) {
  htmlgraphicsText.textContent = customProperties.text;

  // Change the text color based on the theme
  if (theme.isDark) {
    htmlgraphicsText.style.color = 'green';
  } else {
    htmlgraphicsText.style.color = 'red';
  }
}

options.onRender:
const card = htmlNode.querySelector('.wfi-card');
if (!card) return;
const $ = (id) => htmlNode.querySelector('#' + id);
const st = card.__wfi || (card.__wfi = { num: null, raf: null, label: null });

/* ---------- Settings ---------- */
const STALE_MS = 5 * 60 * 1000;
const MAX_POINTS = 120;
const LOCALE = 'en-US';
const LEVELS = [                         // RSSI ranges (dBm)
  { min: -50,       label: 'Excellent', bars: 3 },
  { min: -60,       label: 'Very good', bars: 3 },
  { min: -67,       label: 'Good',      bars: 2 },
  { min: -70,       label: 'Fair',      bars: 2 },
  { min: -80,       label: 'Weak',      bars: 1 },
  { min: -Infinity, label: 'Unusable',  bars: 0 }
];
const PALETTE = [                        // by quality %
  [0, '#f87171'], [30, '#fb923c'], [50, '#facc15'], [70, '#a3e635'], [85, '#4ade80']
];

/* ---------- Helpers ---------- */
const toArr = (v) => {
  if (!v) return [];
  if (Array.isArray(v)) return v;
  if (typeof v.toArray === 'function') return v.toArray();
  if (typeof v.get === 'function') { const a = []; for (let i = 0; i < v.length; i++) a.push(v.get(i)); return a; }
  return Array.from(v);
};
const hexToRgb = (c) => [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16));
const rgbToHex = (a) => '#' + a.map((v) => Math.round(v).toString(16).padStart(2, '0')).join('');
const mix = (c1, c2, k) => { const a = hexToRgb(c1), b = hexToRgb(c2); return rgbToHex(a.map((v, j) => v + (b[j] - v) * k)); };
const colorAt = (t) => {
  if (t <= PALETTE[0][0]) return PALETTE[0][1];
  for (let i = 1; i < PALETTE.length; i++) {
    const [t1, c1] = PALETTE[i];
    if (t <= t1) {
      const [t0, c0] = PALETTE[i - 1];
      return mix(c0, c1, (t - t0) / (t1 - t0));
    }
  }
  return PALETTE[PALETTE.length - 1][1];
};
const quality = (dbm) => Math.max(0, Math.min(100, 2 * (dbm + 100)));
const fmt = (v) => {
  const r = Math.round(v);
  return (r < 0 ? '\u2212' : '') + Math.abs(r).toLocaleString(LOCALE);
};

/* ---------- Data (nulls are skipped) ---------- */
let points = [];
let hasTime = false;
for (const s of (data && data.series) || []) {
  const tf = s.fields.find((f) => f.type === 'time');
  const vf = s.fields.find((f) => f.type === 'number') || s.fields.find((f) => f.type !== 'time');
  if (!vf) continue;
  hasTime = !!tf;
  const ts = tf ? toArr(tf.values) : [];
  toArr(vf.values).forEach((v, i) => {
    if (v === null || v === undefined || v === '') return;
    const n = Number(v);
    if (isNaN(n) || n > 0 || n < -120) return;
    points.push({ t: ts[i] != null ? Number(ts[i]) : i * 30000, v: n });
  });
  break;
}
points.sort((a, b) => a.t - b.t);

if (!points.length) {
  $('wfi-value').textContent = '--';
  $('wfi-q').textContent = '--%';
  $('wfi-label').textContent = 'No data';
  [1, 2, 3].forEach((i) => $('wfi-arc-' + i).classList.remove('is-on'));
  card.classList.add('is-stale');
  return;
}

/* ---------- Calculations ---------- */
const vals = points.map((p) => p.v);
const last = points[points.length - 1];
const cur = last.v;
const q = quality(cur);
const level = LEVELS.find((l) => cur >= l.min);
const accent = colorAt(q);

card.style.setProperty('--accent', accent);
card.style.setProperty('--accent-hi', mix(accent, '#ffffff', 0.3));
card.classList.toggle('is-stale', hasTime && Date.now() - last.t > STALE_MS);

/* ---------- Animated dBm ---------- */
const valEl = $('wfi-value');
if (st.num !== cur) {
  const from = st.num ?? -100;
  cancelAnimationFrame(st.raf);
  const t0 = performance.now();
  const dur = 1000;
  const step = (now) => {
    const k = Math.min(1, (now - t0) / dur);
    const e = 1 - Math.pow(1 - k, 3);
    valEl.textContent = fmt(from + (cur - from) * e);
    if (k < 1) st.raf = requestAnimationFrame(step);
  };
  st.raf = requestAnimationFrame(step);
  st.num = cur;
}

/* ---------- Signal icon ---------- */
[1, 2, 3].forEach((i) => $('wfi-arc-' + i).classList.toggle('is-on', i <= level.bars));

/* ---------- Bottom line ---------- */
const lblEl = $('wfi-label');
if (st.label !== level.label) {
  lblEl.textContent = level.label;
  lblEl.classList.remove('wfi-swap');
  void lblEl.offsetWidth;
  lblEl.classList.add('wfi-swap');
  st.label = level.label;
}
$('wfi-q').textContent = Math.round(q) + '%';

/* ---------- Background sparkline (auto-scaled) ---------- */
const recent = vals.slice(-MAX_POINTS);
const svg = $('wfi-spark-svg');
const w = Math.max(60, svg.clientWidth || 300);
const h = Math.max(20, svg.clientHeight || 60);
svg.setAttribute('viewBox', `0 0 ${w} ${h}`);

let lo = Math.min(...recent), hi = Math.max(...recent);
if (hi - lo < 4) { const mid = (hi + lo) / 2; lo = mid - 2; hi = mid + 2; }
lo -= (hi - lo) * 0.6;
const padT = 4;
const xy = recent.map((v, i) => [
  recent.length === 1 ? w / 2 : (i * w) / (recent.length - 1),
  h - ((v - lo) / (hi - lo)) * (h - padT)
]);
const smooth = (P) => {
  let d = `M${P[0][0].toFixed(1)},${P[0][1].toFixed(1)}`;
  for (let i = 0; i < P.length - 1; i++) {
    const p0 = P[i - 1] || P[i], p1 = P[i], p2 = P[i + 1], p3 = P[i + 2] || p2;
    const t = 1 / 6;
    const c1x = p1[0] + (p2[0] - p0[0]) * t, c1y = p1[1] + (p2[1] - p0[1]) * t;
    const c2x = p2[0] - (p3[0] - p1[0]) * t, c2y = p2[1] - (p3[1] - p1[1]) * t;
    d += ` C${c1x.toFixed(1)},${c1y.toFixed(1)} ${c2x.toFixed(1)},${c2y.toFixed(1)} ${p2[0].toFixed(1)},${p2[1].toFixed(1)}`;
  }
  return d;
};
const lineD = smooth(xy);
$('wfi-spark-line').setAttribute('d', lineD);
const area = $('wfi-spark-area');
area.setAttribute('d', `${lineD} L${w},${h} L0,${h} Z`);
area.classList.add('is-visible');

options.css:
.hum-wrap {
  container-type: inline-size;
  width: 100%;
  height: 100%;
}

.hum-card {
  --accent: #1f60c4;
  --accent-hi: #6fa3ef;
  --bg-1: #0b0f16;
  --bg-2: #141a26;
  --text: #e9edf4;
  --muted: #8892a6;
  --line: rgba(255, 255, 255, 0.07);

  position: relative;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  min-height: 190px;
  padding: 16px 20px 14px;
  border-radius: 18px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 12px;
  color: var(--text);
  font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: linear-gradient(160deg, var(--bg-2) 0%, var(--bg-1) 100%);
  border: 1px solid var(--line);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  animation: hum-enter 0.9s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.hum-card > *:not(.hum-bg) { position: relative; z-index: 1; }

.hum-bg {
  position: absolute;
  inset: -50%;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 22% 45%, var(--accent) 0%, transparent 32%),
    radial-gradient(circle at 85% 80%, var(--accent) 0%, transparent 30%);
  opacity: 0.18;
  filter: blur(40px);
  animation: hum-drift 24s ease-in-out infinite alternate;
}

/* Header */
.hum-header { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.hum-title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}
.hum-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent-hi);
  animation: hum-pulse 2.6s ease-out infinite;
  transition: background 0.8s ease;
}
.hum-card.is-stale .hum-dot { background: #5a6273; animation: none; }
.hum-meta { display: flex; align-items: center; gap: 10px; }
.hum-updated { font-size: 11px; color: var(--muted); font-variant-numeric: tabular-nums; }
.hum-badge {
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.04em;
  padding: 4px 10px;
  border-radius: 999px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
}

/* Body */
.hum-body {
  flex: 1 1 auto;
  min-height: 0;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 24px;
}
.hum-left { display: flex; align-items: center; gap: 16px; }

/* Droplet */
.hum-drop { width: 56px; height: 76px; flex: 0 0 auto; overflow: visible; }
.hum-glow {
  fill: var(--accent);
  opacity: 0.3;
  filter: blur(9px);
  animation: hum-glow 4s ease-in-out infinite;
  transition: fill 1s ease;
}
.hum-glass {
  fill: rgba(255, 255, 255, 0.03);
  stroke: rgba(255, 255, 255, 0.22);
  stroke-width: 1.8;
  stroke-linejoin: round;
}
.hum-liquid {
  transform: translateY(70px);
  transition: transform 1.8s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.hum-wave--front { animation: hum-wave 3.6s linear infinite; }
.hum-wave--back {
  fill: var(--accent-hi);
  opacity: 0.3;
  animation: hum-wave-rev 5.8s linear infinite;
  transition: fill 1s ease;
}
.hum-liq-a { stop-color: var(--accent-hi); stop-opacity: 0.95; transition: stop-color 1s ease; }
.hum-liq-b { stop-color: var(--accent); stop-opacity: 0.95; transition: stop-color 1s ease; }
.hum-vapor circle {
  fill: rgba(255, 255, 255, 0.6);
  opacity: 0;
  animation: hum-rise 4.2s ease-in infinite;
}
.hum-shine {
  fill: none;
  stroke: rgba(255, 255, 255, 0.35);
  stroke-width: 2;
  stroke-linecap: round;
}

/* Reading */
.hum-reading { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.hum-value { display: flex; align-items: flex-start; gap: 4px; line-height: 1; }
#hum-value {
  font-size: 46px;
  font-weight: 300;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
  background: linear-gradient(180deg, #ffffff 0%, #c9d4e6 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.hum-unit { font-size: 18px; font-weight: 500; color: var(--muted); margin-top: 4px; }
.hum-level { font-size: 14px; font-weight: 500; color: var(--accent-hi); transition: color 0.8s ease; white-space: nowrap; }
.hum-swap { animation: hum-swap 0.6s cubic-bezier(0.2, 0.8, 0.2, 1); }

.hum-trend {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: fit-content;
  white-space: nowrap;
  font-size: 12px;
  font-weight: 500;
  padding: 4px 10px 4px 8px;
  border-radius: 999px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
  transition: color 0.5s ease, background 0.5s ease;
}
.hum-trend svg {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.hum-trend--up { color: #8fb8ff; background: rgba(111, 163, 239, 0.1); }
.hum-trend--down { color: #67e8f9; background: rgba(103, 232, 249, 0.08); }

/* Chart */
.hum-right { display: flex; flex-direction: column; gap: 6px; min-width: 0; min-height: 0; }
.hum-chips { display: flex; justify-content: flex-end; gap: 6px; flex-wrap: wrap; }
.hum-chip {
  font-size: 11px;
  padding: 3px 9px;
  border-radius: 999px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--line);
  font-variant-numeric: tabular-nums;
}
.hum-chip b { color: var(--text); font-weight: 600; margin-left: 4px; }

.hum-svg { flex: 1 1 auto; width: 100%; min-height: 80px; overflow: visible; }
.hum-grid line { stroke: var(--line); stroke-width: 1; }
.hum-grid text {
  fill: var(--muted);
  font-size: 9.5px;
  font-family: inherit;
  font-variant-numeric: tabular-nums;
}
.hum-band { fill: rgba(111, 163, 239, 0.07); transition: opacity 0.8s ease; }
.hum-band-label {
  fill: rgba(143, 184, 255, 0.6);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.12em;
  font-family: inherit;
}
.hum-band-edge { stroke: rgba(111, 163, 239, 0.25); stroke-width: 1; stroke-dasharray: 3 4; }
.hum-band-group { transition: opacity 0.8s ease; }
.hum-band-group.is-hidden { opacity: 0; }

.hum-line {
  fill: none;
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 0 6px var(--accent));
}
.hum-area { opacity: 0; transition: opacity 1.2s ease 0.4s; }
.hum-area.is-visible { opacity: 1; }
.hum-area-a { stop-color: var(--accent); stop-opacity: 0.32; transition: stop-color 1s ease; }
.hum-area-b { stop-color: var(--accent); stop-opacity: 0; }

.hum-marks circle { fill: var(--bg-1); stroke-width: 1.6; }
.hum-marks text {
  font-size: 10px;
  font-weight: 600;
  font-family: inherit;
  text-anchor: middle;
  font-variant-numeric: tabular-nums;
}
.hum-marks { animation: hum-fade 1s ease 1.4s both; }

.hum-pt { fill: #ffffff; }
.hum-ring {
  fill: none;
  stroke: var(--accent-hi);
  stroke-width: 1.5;
  transform-box: fill-box;
  transform-origin: center;
  animation: hum-ring 2.4s ease-out infinite;
}

.hum-xaxis {
  display: flex;
  justify-content: space-between;
  padding-left: 30px;
  font-size: 10px;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

/* Narrow panels: stack */
@container (max-width: 560px) {
  .hum-body { grid-template-columns: 1fr; gap: 14px; }
  .hum-chips { justify-content: flex-start; }
}

/* Animations */
@keyframes hum-enter {
  from { opacity: 0; transform: translateY(10px) scale(0.99); }
  to   { opacity: 1; transform: none; }
}
@keyframes hum-drift {
  from { transform: translate(0, 0); }
  to   { transform: translate(6%, -5%); }
}
@keyframes hum-pulse {
  0%   { box-shadow: 0 0 0 0 var(--accent-hi); }
  70%  { box-shadow: 0 0 0 8px transparent; }
  100% { box-shadow: 0 0 0 0 transparent; }
}
@keyframes hum-glow { 0%, 100% { opacity: 0.22; } 50% { opacity: 0.45; } }
@keyframes hum-wave     { from { transform: translateX(0); }    to { transform: translateX(40px); } }
@keyframes hum-wave-rev { from { transform: translateX(40px); } to { transform: translateX(0); } }
@keyframes hum-rise {
  0%   { transform: translateY(0);     opacity: 0; }
  25%  { opacity: 0.7; }
  100% { transform: translateY(-44px); opacity: 0; }
}
@keyframes hum-ring {
  0%   { transform: scale(1);   opacity: 0.9; }
  100% { transform: scale(3.2); opacity: 0; }
}
@keyframes hum-swap {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: none; }
}
@keyframes hum-fade { from { opacity: 0; } to { opacity: 1; } }

@media (prefers-reduced-motion: reduce) {
  .hum-card, .hum-card * { animation: none !important; transition: none !important; }
}

options.onInit:
// Sets the text from customProperties
const htmlgraphicsText = htmlNode.getElementById('htmlgraphics-text');

if (htmlgraphicsText) {
  htmlgraphicsText.textContent = customProperties.text;

  // Change the text color based on the theme
  if (theme.isDark) {
    htmlgraphicsText.style.color = 'green';
  } else {
    htmlgraphicsText.style.color = 'red';
  }
}

options.onRender:
const card = htmlNode.querySelector('.hum-card');
if (!card) return;
const $ = (id) => htmlNode.querySelector('#' + id);
const st = card.__hum || (card.__hum = { num: null, raf: null, drawn: false, level: null, init: false });

/* ---------- Settings ---------- */
const COMFORT_MIN = 40;                  // comfort band on the chart (%)
const COMFORT_MAX = 60;
const RATE_WINDOW_MS = 30 * 60 * 1000;
const RATE_THRESHOLD = 1;                // %/h needed to leave "Stable"
const STALE_MS = 5 * 60 * 1000;
const MAX_POINTS = 240;
const LOCALE = 'en-US';
const PALETTE = [                        // blue family, base rgb(31, 96, 196)
  [0, '#38bdf8'], [35, '#3b8ee8'], [65, '#1f60c4'], [100, '#2c3fb8']
];
const LEVELS = [
  { max: 25,       label: 'Very dry' },
  { max: 40,       label: 'Dry' },
  { max: 60,       label: 'Comfortable' },
  { max: 70,       label: 'Humid' },
  { max: 85,       label: 'Very humid' },
  { max: Infinity, label: 'Saturated' }
];

/* ---------- Helpers ---------- */
const toArr = (v) => {
  if (!v) return [];
  if (Array.isArray(v)) return v;
  if (typeof v.toArray === 'function') return v.toArray();
  if (typeof v.get === 'function') { const a = []; for (let i = 0; i < v.length; i++) a.push(v.get(i)); return a; }
  return Array.from(v);
};
const hexToRgb = (c) => [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16));
const rgbToHex = (a) => '#' + a.map((v) => Math.round(v).toString(16).padStart(2, '0')).join('');
const mix = (c1, c2, k) => { const a = hexToRgb(c1), b = hexToRgb(c2); return rgbToHex(a.map((v, j) => v + (b[j] - v) * k)); };
const colorAt = (t) => {
  if (t <= PALETTE[0][0]) return PALETTE[0][1];
  for (let i = 1; i < PALETTE.length; i++) {
    const [t1, c1] = PALETTE[i];
    if (t <= t1) {
      const [t0, c0] = PALETTE[i - 1];
      return mix(c0, c1, (t - t0) / (t1 - t0));
    }
  }
  return PALETTE[PALETTE.length - 1][1];
};
const lighten = (c, k = 0.38) => mix(c, '#ffffff', k);
const fmt = (v) => v.toLocaleString(LOCALE, { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const fmtTime = (t) => new Date(t).toLocaleTimeString(LOCALE, { hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });

/* ---------- Data ---------- */
let points = [];
let hasTime = false;
for (const s of (data && data.series) || []) {
  const tf = s.fields.find((f) => f.type === 'time');
  const vf = s.fields.find((f) => f.type === 'number');
  if (!vf) continue;
  hasTime = !!tf;
  const ts = tf ? toArr(tf.values) : [];
  toArr(vf.values).forEach((v, i) => {
    if (v !== null && v !== undefined && !isNaN(v) && Number(v) >= 0 && Number(v) <= 100) {
      points.push({ t: ts[i] != null ? Number(ts[i]) : i * 60000, v: Number(v) });
    }
  });
  break;
}
points.sort((a, b) => a.t - b.t);

if (!points.length) {
  $('hum-value').textContent = '--';
  $('hum-level').textContent = 'No data in range';
  $('hum-trend').innerHTML = '';
  card.classList.add('is-stale');
  return;
}

/* ---------- Calculations ---------- */
const vals0 = points.map((p) => p.v);
const last = points[points.length - 1];
const cur = last.v;
const hMin = Math.min(...vals0);
const hMax = Math.max(...vals0);
const hAvg = vals0.reduce((a, b) => a + b, 0) / vals0.length;
const level = LEVELS.find((l) => cur < l.max);
const accent = colorAt(cur);

const win = points.filter((p) => p.t >= last.t - RATE_WINDOW_MS);
let rate = 0;
if (win.length >= 3) {
  const t0 = win[0].t;
  let sx = 0, sy = 0, sxx = 0, sxy = 0;
  win.forEach((p) => {
    const x = (p.t - t0) / 3.6e6;
    sx += x; sy += p.v; sxx += x * x; sxy += x * p.v;
  });
  const n = win.length;
  const den = n * sxx - sx * sx;
  if (den) rate = (n * sxy - sx * sy) / den;
}
const trend = rate > RATE_THRESHOLD ? 'up' : rate < -RATE_THRESHOLD ? 'down' : 'flat';

/* ---------- Theme and state ---------- */
card.style.setProperty('--accent', accent);
card.style.setProperty('--accent-hi', lighten(accent));
card.classList.toggle('is-stale', hasTime && Date.now() - last.t > STALE_MS);

/* ---------- Animated value ---------- */
const valEl = $('hum-value');
if (st.num !== cur) {
  const from = st.num ?? 0;
  cancelAnimationFrame(st.raf);
  const t0 = performance.now();
  const dur = 1200;
  const step = (now) => {
    const k = Math.min(1, (now - t0) / dur);
    const e = 1 - Math.pow(1 - k, 3);
    valEl.textContent = fmt(from + (cur - from) * e);
    if (k < 1) st.raf = requestAnimationFrame(step);
  };
  st.raf = requestAnimationFrame(step);
  st.num = cur;
}

/* ---------- Droplet ---------- */
const liquid = $('hum-liquid');
if (!st.init) { liquid.getBoundingClientRect(); st.init = true; }
const ratio = Math.max(0, Math.min(1, cur / 100));
liquid.style.transform = `translateY(${(70 - ratio * 66).toFixed(2)}px)`;

/* ---------- Level ---------- */
const lvlEl = $('hum-level');
if (st.level !== level.label) {
  lvlEl.textContent = level.label;
  lvlEl.classList.remove('hum-swap');
  void lvlEl.offsetWidth;
  lvlEl.classList.add('hum-swap');
  st.level = level.label;
}

/* ---------- Trend ---------- */
const ICONS = {
  up:   '<svg viewBox="0 0 16 16"><path d="M4 10l4-4 4 4"/></svg>',
  down: '<svg viewBox="0 0 16 16"><path d="M4 6l4 4 4-4"/></svg>',
  flat: '<svg viewBox="0 0 16 16"><path d="M3 8h10"/></svg>'
};
const rateTxt = Math.abs(rate).toFixed(1) + ' %/h';
const TEXT = { up: 'Rising +' + rateTxt, down: 'Falling -' + rateTxt, flat: 'Stable' };
const trendEl = $('hum-trend');
trendEl.className = 'hum-trend hum-trend--' + trend;
trendEl.innerHTML = ICONS[trend] + '<span>' + TEXT[trend] + '</span>';

/* ---------- Chips and header ---------- */
$('hum-min').textContent = fmt(hMin) + '%';
$('hum-avg').textContent = fmt(hAvg) + '%';
$('hum-max').textContent = fmt(hMax) + '%';
$('hum-updated').textContent = hasTime ? 'Updated ' + fmtTime(last.t) : '';

/* ---------- Chart ---------- */
const recent = points.slice(-MAX_POINTS);
const vals = recent.map((p) => p.v);

const svg = $('hum-svg');
const w = Math.max(80, svg.clientWidth || 300);
const h = Math.max(60, svg.clientHeight || 100);
svg.setAttribute('viewBox', `0 0 ${w} ${h}`);

let lo = Math.min(...vals), hi = Math.max(...vals);
if (hi - lo < 4) { const mid = (hi + lo) / 2; lo = mid - 2; hi = mid + 2; }
const padV = (hi - lo) * 0.15;
lo = Math.max(0, lo - padV);
hi = Math.min(100, hi + padV);

const padL = 30, padR = 6, padT = 16, padB = 16;
const xOf = (i) => vals.length === 1 ? (padL + w) / 2 : padL + (i * (w - padL - padR)) / (vals.length - 1);
const yOf = (v) => h - padB - ((v - lo) / (hi - lo)) * (h - padT - padB);

/* Grid */
const rawStep = (hi - lo) / 3;
const step = [0.5, 1, 2, 5, 10, 20, 25].find((s) => s >= rawStep) || 25;
const dec = step < 1 ? 1 : 0;
let grid = '';
for (let v = Math.ceil(lo / step) * step; v <= hi + 1e-9; v += step) {
  const y = yOf(v).toFixed(1);
  grid += `<line x1="${padL}" x2="${w - padR}" y1="${y}" y2="${y}"/>`;
  grid += `<text x="0" y="${(Number(y) + 3).toFixed(1)}">${v.toFixed(dec)}%</text>`;
}
$('hum-grid').innerHTML = grid;

/* Comfort band */
const bandGroup = $('hum-band-group');
const bLo = Math.max(lo, COMFORT_MIN);
const bHi = Math.min(hi, COMFORT_MAX);
if (bHi > bLo) {
  const yTop = yOf(bHi), yBot = yOf(bLo);
  const band = $('hum-band');
  band.setAttribute('x', padL);
  band.setAttribute('y', yTop.toFixed(1));
  band.setAttribute('width', w - padL - padR);
  band.setAttribute('height', Math.max(0, yBot - yTop).toFixed(1));
  [['hum-band-top', yTop, COMFORT_MAX <= hi], ['hum-band-bot', yBot, COMFORT_MIN >= lo]].forEach(([id, y, show]) => {
    const l = $(id);
    l.setAttribute('x1', padL);
    l.setAttribute('x2', w - padR);
    l.setAttribute('y1', y.toFixed(1));
    l.setAttribute('y2', y.toFixed(1));
    l.style.display = show ? '' : 'none';
  });
  const lbl = $('hum-band-label');
  lbl.setAttribute('x', (w - padR - 4).toFixed(1));
  lbl.setAttribute('y', (yTop + 11).toFixed(1));
  lbl.style.display = yBot - yTop > 14 ? '' : 'none';
  bandGroup.classList.remove('is-hidden');
} else {
  bandGroup.classList.add('is-hidden');
}

/* Line gradient (blue family, lightened for contrast) */
const lg = $('humLineGrad');
lg.setAttribute('y1', yOf(lo).toFixed(1));
lg.setAttribute('y2', yOf(hi).toFixed(1));
let stops = '';
for (let k = 0; k <= 6; k++) {
  const t = lo + ((hi - lo) * k) / 6;
  stops += `<stop offset="${(k / 6).toFixed(3)}" stop-color="${lighten(colorAt(t), 0.3)}"/>`;
}
lg.innerHTML = stops;

/* Smooth path */
const xy = vals.map((v, i) => [xOf(i), yOf(v)]);
const smooth = (P) => {
  let d = `M${P[0][0].toFixed(1)},${P[0][1].toFixed(1)}`;
  for (let i = 0; i < P.length - 1; i++) {
    const p0 = P[i - 1] || P[i], p1 = P[i], p2 = P[i + 1], p3 = P[i + 2] || p2;
    const t = 1 / 6;
    const c1x = p1[0] + (p2[0] - p0[0]) * t, c1y = p1[1] + (p2[1] - p0[1]) * t;
    const c2x = p2[0] - (p3[0] - p1[0]) * t, c2y = p2[1] - (p3[1] - p1[1]) * t;
    d += ` C${c1x.toFixed(1)},${c1y.toFixed(1)} ${c2x.toFixed(1)},${c2y.toFixed(1)} ${p2[0].toFixed(1)},${p2[1].toFixed(1)}`;
  }
  return d;
};
const lineD = smooth(xy);
const line = $('hum-line');
const area = $('hum-area');
line.setAttribute('d', lineD);
area.setAttribute('d', `${lineD} L${xy[xy.length - 1][0].toFixed(1)},${h - padB} L${xy[0][0].toFixed(1)},${h - padB} Z`);

const [lx, ly] = xy[xy.length - 1];
['hum-dot', 'hum-ring'].forEach((id) => {
  const c = $(id);
  c.setAttribute('cx', lx.toFixed(1));
  c.setAttribute('cy', ly.toFixed(1));
});

/* Min / max markers */
let marks = '';
const iMax = vals.indexOf(Math.max(...vals));
const iMin = vals.indexOf(Math.min(...vals));
if (iMax !== iMin) {
  const clampX = (x) => Math.max(padL + 14, Math.min(w - padR - 14, x));
  const [mxX, mxY] = xy[iMax];
  const [mnX, mnY] = xy[iMin];
  const cMax = lighten(colorAt(vals[iMax]), 0.35);
  const cMin = lighten(colorAt(vals[iMin]), 0.35);
  marks += `<circle cx="${mxX.toFixed(1)}" cy="${mxY.toFixed(1)}" r="3" stroke="${cMax}"/>`;
  marks += `<text x="${clampX(mxX).toFixed(1)}" y="${(mxY - 7).toFixed(1)}" fill="${cMax}">${fmt(vals[iMax])}%</text>`;
  marks += `<circle cx="${mnX.toFixed(1)}" cy="${mnY.toFixed(1)}" r="3" stroke="${cMin}"/>`;
  marks += `<text x="${clampX(mnX).toFixed(1)}" y="${(mnY + 14).toFixed(1)}" fill="${cMin}">${fmt(vals[iMin])}%</text>`;
}
$('hum-marks').innerHTML = marks;

/* Draw-in animation */
if (!st.drawn) {
  const len = line.getTotalLength();
  line.style.transition = 'none';
  line.style.strokeDasharray = len;
  line.style.strokeDashoffset = len;
  line.getBoundingClientRect();
  line.style.transition = 'stroke-dashoffset 1.8s cubic-bezier(0.4, 0, 0.2, 1)';
  line.style.strokeDashoffset = '0';
  setTimeout(() => {
    line.style.transition = '';
    line.style.strokeDasharray = 'none';
  }, 1900);
  st.drawn = true;
}
area.classList.add('is-visible');

/* X axis */
if (hasTime) {
  $('hum-x0').textContent = fmtTime(recent[0].t);
  $('hum-x1').textContent = fmtTime(recent[Math.floor(recent.length / 2)].t);
  $('hum-x2').textContent = fmtTime(recent[recent.length - 1].t);
} else {
  $('hum-x0').textContent = $('hum-x1').textContent = $('hum-x2').textContent = '';
}

options.css:
.itp-wrap {
  width: 100%;
  height: 100%;
}

.itp-card {
  --accent: #4ade80;
  --accent-hi: #86efac;
  --bg-1: #0b0f16;
  --bg-2: #151b26;
  --text: #e9edf4;
  --muted: #8892a6;
  --line: rgba(255, 255, 255, 0.07);

  position: relative;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  min-height: 120px;
  padding: 12px 14px 12px;
  border-radius: 16px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 4px;
  color: var(--text);
  font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: linear-gradient(160deg, var(--bg-2) 0%, var(--bg-1) 100%);
  border: 1px solid var(--line);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  animation: itp-enter 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.itp-card > *:not(.itp-bg):not(.itp-spark) { position: relative; z-index: 1; }

.itp-bg {
  position: absolute;
  inset: -50%;
  z-index: 0;
  pointer-events: none;
  background: radial-gradient(circle at 50% 48%, var(--accent) 0%, transparent 26%);
  opacity: 0.12;
  filter: blur(30px);
  transition: background 1s ease;
  animation: itp-glow 5s ease-in-out infinite;
}

/* Background sparkline */
.itp-spark {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 55%;
  z-index: 0;
  pointer-events: none;
  opacity: 0.5;
}
.itp-spark svg { width: 100%; height: 100%; display: block; }
.itp-spark-line {
  fill: none;
  stroke: var(--accent);
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: stroke 1s ease;
}
.itp-spark-area { opacity: 0; transition: opacity 1.2s ease 0.3s; }
.itp-spark-area.is-visible { opacity: 1; }
.itp-spark-a { stop-color: var(--accent); stop-opacity: 0.28; transition: stop-color 1s ease; }
.itp-spark-b { stop-color: var(--accent); stop-opacity: 0; }

/* Header */
.itp-header { display: flex; align-items: center; }
.itp-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
}
.itp-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent);
  animation: itp-pulse 2.6s ease-out infinite;
  transition: background 0.8s ease;
}
.itp-card.is-stale .itp-dot { background: #5a6273; animation: none; }

/* Center value */
.itp-center {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  container-type: size;
}
.itp-value {
  display: flex;
  align-items: flex-start;
  gap: 3px;
  line-height: 1;
}
#itp-value {
  font-size: clamp(24px, 55cqh, 52px);
  font-weight: 300;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
  background: linear-gradient(180deg, #ffffff 0%, #c9d1df 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.itp-unit {
  font-size: clamp(11px, 20cqh, 18px);
  font-weight: 500;
  color: var(--muted);
  margin-top: 0.25em;
}

/* Bottom level */
.itp-level {
  text-align: center;
  font-size: 13px;
  font-weight: 500;
  color: var(--accent-hi);
  white-space: nowrap;
  transition: color 0.8s ease;
}
.itp-swap { animation: itp-swap 0.6s cubic-bezier(0.2, 0.8, 0.2, 1); }

/* Animations */
@keyframes itp-enter {
  from { opacity: 0; transform: translateY(8px) scale(0.99); }
  to   { opacity: 1; transform: none; }
}
@keyframes itp-pulse {
  0%   { box-shadow: 0 0 0 0 var(--accent); }
  70%  { box-shadow: 0 0 0 7px transparent; }
  100% { box-shadow: 0 0 0 0 transparent; }
}
@keyframes itp-glow { 0%, 100% { opacity: 0.1; } 50% { opacity: 0.18; } }
@keyframes itp-swap {
  from { opacity: 0; transform: translateY(3px); }
  to   { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .itp-card, .itp-card * { animation: none !important; transition: none !important; }
}

