options.onRender:
const card = htmlNode.querySelector('.itp-card');
if (!card) return;
const $ = (id) => htmlNode.querySelector('#' + id);
const st = card.__itp || (card.__itp = { num: null, raf: null, level: null });

/* ---------- Settings ---------- */
const STALE_MS = 15 * 60 * 1000;         // sensor reports every ~5 min
const MAX_POINTS = 120;
const LOCALE = 'en-US';
const PALETTE = [
  [0, '#38bdf8'], [15, '#2dd4bf'], [25, '#4ade80'],
  [35, '#facc15'], [45, '#fb923c'], [55, '#f87171']
];
const LEVELS = [                          // Li-ion battery / electronics ranges
  { max: 0,        label: 'Too cold to charge' },
  { max: 10,       label: 'Cold' },
  { max: 35,       label: 'Normal' },
  { max: 45,       label: 'Warm' },
  { max: 55,       label: 'Hot' },
  { max: Infinity, label: 'Critical' }
];

/* ---------- Helpers ---------- */
const toArr = (v) => {
  if (!v) return [];
  if (Array.isArray(v)) return v;
  if (typeof v.toArray === 'function') return v.toArray();
  if (typeof v.get === 'function') { const a = []; for (let i = 0; i < v.length; i++) a.push(v.get(i)); return a; }
  return Array.from(v);
};
const hexToRgb = (c) => [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16));
const rgbToHex = (a) => '#' + a.map((v) => Math.round(v).toString(16).padStart(2, '0')).join('');
const mix = (c1, c2, k) => { const a = hexToRgb(c1), b = hexToRgb(c2); return rgbToHex(a.map((v, j) => v + (b[j] - v) * k)); };
const colorAt = (t) => {
  if (t <= PALETTE[0][0]) return PALETTE[0][1];
  for (let i = 1; i < PALETTE.length; i++) {
    const [t1, c1] = PALETTE[i];
    if (t <= t1) {
      const [t0, c0] = PALETTE[i - 1];
      return mix(c0, c1, (t - t0) / (t1 - t0));
    }
  }
  return PALETTE[PALETTE.length - 1][1];
};
const fmt = (v) => v.toLocaleString(LOCALE, { minimumFractionDigits: 1, maximumFractionDigits: 1 });

/* ---------- Data (nulls are skipped) ---------- */
let points = [];
let hasTime = false;
for (const s of (data && data.series) || []) {
  const tf = s.fields.find((f) => f.type === 'time');
  const vf = s.fields.find((f) => f.type === 'number') || s.fields.find((f) => f.type !== 'time');
  if (!vf) continue;
  hasTime = !!tf;
  const ts = tf ? toArr(tf.values) : [];
  toArr(vf.values).forEach((v, i) => {
    if (v === null || v === undefined || v === '') return;
    const n = Number(v);
    if (isNaN(n) || n < -40 || n > 125) return;
    points.push({ t: ts[i] != null ? Number(ts[i]) : i * 300000, v: n });
  });
  break;
}
points.sort((a, b) => a.t - b.t);

if (!points.length) {
  $('itp-value').textContent = '--';
  $('itp-level').textContent = 'No data in range';
  card.classList.add('is-stale');
  return;
}

/* ---------- Calculations ---------- */
const vals = points.map((p) => p.v);
const last = points[points.length - 1];
const cur = last.v;
const level = LEVELS.find((l) => cur < l.max);
const accent = colorAt(cur);

card.style.setProperty('--accent', accent);
card.style.setProperty('--accent-hi', mix(accent, '#ffffff', 0.3));
card.classList.toggle('is-stale', hasTime && Date.now() - last.t > STALE_MS);

/* ---------- Animated value ---------- */
const valEl = $('itp-value');
if (st.num !== cur) {
  const from = st.num ?? 0;
  cancelAnimationFrame(st.raf);
  const t0 = performance.now();
  const dur = 1100;
  const step = (now) => {
    const k = Math.min(1, (now - t0) / dur);
    const e = 1 - Math.pow(1 - k, 3);
    valEl.textContent = fmt(from + (cur - from) * e);
    if (k < 1) st.raf = requestAnimationFrame(step);
  };
  st.raf = requestAnimationFrame(step);
  st.num = cur;
}

/* ---------- Level ---------- */
const lvlEl = $('itp-level');
if (st.level !== level.label) {
  lvlEl.textContent = level.label;
  lvlEl.classList.remove('itp-swap');
  void lvlEl.offsetWidth;
  lvlEl.classList.add('itp-swap');
  st.level = level.label;
}

/* ---------- Background sparkline (auto-scaled) ---------- */
const recent = vals.slice(-MAX_POINTS);
const svg = $('itp-spark-svg');
const w = Math.max(60, svg.clientWidth || 300);
const h = Math.max(20, svg.clientHeight || 60);
svg.setAttribute('viewBox', `0 0 ${w} ${h}`);

let lo = Math.min(...recent), hi = Math.max(...recent);
if (hi - lo < 2) { const mid = (hi + lo) / 2; lo = mid - 1; hi = mid + 1; }
lo -= (hi - lo) * 0.6;
const padT = 4;
const xy = recent.map((v, i) => [
  recent.length === 1 ? w / 2 : (i * w) / (recent.length - 1),
  h - ((v - lo) / (hi - lo)) * (h - padT)
]);
const smooth = (P) => {
  let d = `M${P[0][0].toFixed(1)},${P[0][1].toFixed(1)}`;
  for (let i = 0; i < P.length - 1; i++) {
    const p0 = P[i - 1] || P[i], p1 = P[i], p2 = P[i + 1], p3 = P[i + 2] || p2;
    const t = 1 / 6;
    const c1x = p1[0] + (p2[0] - p0[0]) * t, c1y = p1[1] + (p2[1] - p0[1]) * t;
    const c2x = p2[0] - (p3[0] - p1[0]) * t, c2y = p2[1] - (p3[1] - p1[1]) * t;
    d += ` C${c1x.toFixed(1)},${c1y.toFixed(1)} ${c2x.toFixed(1)},${c2y.toFixed(1)} ${p2[0].toFixed(1)},${p2[1].toFixed(1)}`;
  }
  return d;
};
const lineD = smooth(xy);
$('itp-spark-line').setAttribute('d', lineD);
const area = $('itp-spark-area');
area.setAttribute('d', `${lineD} L${w},${h} L0,${h} Z`);
area.classList.add('is-visible');

options.css:
.prs-wrap {
  container-type: inline-size;
  width: 100%;
  height: 100%;
}

.prs-card {
  --accent: #8f3bb8;
  --accent-hi: #c084e0;
  --bg-1: #0b0f16;
  --bg-2: #171624;
  --text: #e9edf4;
  --muted: #8892a6;
  --line: rgba(255, 255, 255, 0.07);

  position: relative;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  min-height: 190px;
  padding: 16px 20px 14px;
  border-radius: 18px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 12px;
  color: var(--text);
  font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: linear-gradient(160deg, var(--bg-2) 0%, var(--bg-1) 100%);
  border: 1px solid var(--line);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  animation: prs-enter 0.9s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.prs-card > *:not(.prs-bg) { position: relative; z-index: 1; }

.prs-bg {
  position: absolute;
  inset: -50%;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 22% 45%, var(--accent) 0%, transparent 32%),
    radial-gradient(circle at 85% 80%, var(--accent) 0%, transparent 28%);
  opacity: 0.17;
  filter: blur(40px);
  animation: prs-drift 24s ease-in-out infinite alternate;
}

/* Header */
.prs-header { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.prs-title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}
.prs-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent-hi);
  animation: prs-pulse 2.6s ease-out infinite;
  transition: background 0.8s ease;
}
.prs-card.is-stale .prs-dot { background: #5a6273; animation: none; }
.prs-meta { display: flex; align-items: center; gap: 10px; }
.prs-updated { font-size: 11px; color: var(--muted); font-variant-numeric: tabular-nums; }
.prs-badge {
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.04em;
  padding: 4px 10px;
  border-radius: 999px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
}

/* Body */
.prs-body {
  flex: 1 1 auto;
  min-height: 0;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 24px;
}
.prs-left { display: flex; align-items: center; gap: 16px; }

/* Barometer dial */
.prs-dial { width: 80px; height: 80px; flex: 0 0 auto; overflow: visible; }
.prs-glow {
  fill: var(--accent);
  opacity: 0.28;
  filter: blur(10px);
  animation: prs-glow 4.4s ease-in-out infinite;
  transition: fill 1s ease;
}
.prs-face {
  fill: rgba(255, 255, 255, 0.03);
  stroke: rgba(255, 255, 255, 0.18);
  stroke-width: 1.6;
}
.prs-track {
  fill: none;
  stroke: rgba(255, 255, 255, 0.07);
  stroke-width: 4;
  stroke-linecap: round;
}
.prs-progress {
  fill: none;
  stroke-width: 4;
  stroke-linecap: round;
  stroke-dasharray: 100;
  stroke-dashoffset: 100;
  filter: drop-shadow(0 0 4px var(--accent));
  transition: stroke-dashoffset 1.8s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.prs-arc-a { stop-color: var(--accent); transition: stop-color 1s ease; }
.prs-arc-b { stop-color: var(--accent-hi); transition: stop-color 1s ease; }
.prs-ticks line { stroke: rgba(255, 255, 255, 0.3); stroke-width: 1.1; stroke-linecap: round; }
.prs-ticks line.minor { stroke: rgba(255, 255, 255, 0.13); }

.prs-needle {
  transform-box: view-box;
  transform-origin: 40px 40px;
  transform: rotate(-120deg);
  transition: transform 2s cubic-bezier(0.34, 1.45, 0.64, 1);
}
.prs-needle-wobble {
  transform-box: view-box;
  transform-origin: 40px 40px;
  animation: prs-wobble 5.5s ease-in-out infinite;
}
.prs-needle-tip { fill: #ffffff; filter: drop-shadow(0 0 4px var(--accent-hi)); }
.prs-needle-tail { fill: var(--accent-hi); transition: fill 1s ease; }
.prs-hub { fill: var(--bg-1); stroke: var(--accent-hi); stroke-width: 2; transition: stroke 1s ease; }
.prs-dial-unit {
  fill: var(--muted);
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.12em;
  font-family: inherit;
  text-anchor: middle;
}

/* Reading */
.prs-reading { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.prs-value { display: flex; align-items: flex-start; gap: 5px; line-height: 1; }
#prs-value {
  font-size: 42px;
  font-weight: 300;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  background: linear-gradient(180deg, #ffffff 0%, #d3c9e3 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.prs-unit { font-size: 15px; font-weight: 500; color: var(--muted); margin-top: 5px; }
.prs-level { font-size: 14px; font-weight: 500; color: var(--accent-hi); transition: color 0.8s ease; white-space: nowrap; }
.prs-swap { animation: prs-swap 0.6s cubic-bezier(0.2, 0.8, 0.2, 1); }

.prs-trend {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: fit-content;
  white-space: nowrap;
  font-size: 12px;
  font-weight: 500;
  padding: 4px 10px 4px 8px;
  border-radius: 999px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
  transition: color 0.5s ease, background 0.5s ease;
}
.prs-trend svg {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.prs-trend--up { color: #d8a8f0; background: rgba(192, 132, 224, 0.1); }
.prs-trend--down { color: #f0a8c8; background: rgba(240, 168, 200, 0.08); }

/* Chart */
.prs-right { display: flex; flex-direction: column; gap: 6px; min-width: 0; min-height: 0; }
.prs-chips { display: flex; justify-content: flex-end; gap: 6px; flex-wrap: wrap; }
.prs-chip {
  font-size: 11px;
  padding: 3px 9px;
  border-radius: 999px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--line);
  font-variant-numeric: tabular-nums;
}
.prs-chip b { color: var(--text); font-weight: 600; margin-left: 4px; }

.prs-svg { flex: 1 1 auto; width: 100%; min-height: 80px; overflow: visible; }
.prs-grid line { stroke: var(--line); stroke-width: 1; }
.prs-grid text {
  fill: var(--muted);
  font-size: 9.5px;
  font-family: inherit;
  font-variant-numeric: tabular-nums;
}
.prs-ref { transition: opacity 0.8s ease; }
.prs-ref.is-hidden { opacity: 0; }
.prs-ref line { stroke: rgba(192, 132, 224, 0.4); stroke-width: 1; stroke-dasharray: 3 4; }
.prs-ref text {
  fill: rgba(192, 132, 224, 0.7);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.1em;
  font-family: inherit;
}

.prs-line {
  fill: none;
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 0 6px var(--accent));
}
.prs-area { opacity: 0; transition: opacity 1.2s ease 0.4s; }
.prs-area.is-visible { opacity: 1; }
.prs-area-a { stop-color: var(--accent); stop-opacity: 0.32; transition: stop-color 1s ease; }
.prs-area-b { stop-color: var(--accent); stop-opacity: 0; }

.prs-marks circle { fill: var(--bg-1); stroke-width: 1.6; }
.prs-marks text {
  font-size: 10px;
  font-weight: 600;
  font-family: inherit;
  text-anchor: middle;
  font-variant-numeric: tabular-nums;
}
.prs-marks { animation: prs-fade 1s ease 1.4s both; }

.prs-pt { fill: #ffffff; }
.prs-ring {
  fill: none;
  stroke: var(--accent-hi);
  stroke-width: 1.5;
  transform-box: fill-box;
  transform-origin: center;
  animation: prs-ring 2.4s ease-out infinite;
}

.prs-xaxis {
  display: flex;
  justify-content: space-between;
  padding-left: 40px;
  font-size: 10px;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

/* Narrow panels: stack */
@container (max-width: 580px) {
  .prs-body { grid-template-columns: 1fr; gap: 14px; }
  .prs-chips { justify-content: flex-start; }
}

/* Animations */
@keyframes prs-enter {
  from { opacity: 0; transform: translateY(10px) scale(0.99); }
  to   { opacity: 1; transform: none; }
}
@keyframes prs-drift {
  from { transform: translate(0, 0); }
  to   { transform: translate(6%, -5%); }
}
@keyframes prs-pulse {
  0%   { box-shadow: 0 0 0 0 var(--accent-hi); }
  70%  { box-shadow: 0 0 0 8px transparent; }
  100% { box-shadow: 0 0 0 0 transparent; }
}
@keyframes prs-glow { 0%, 100% { opacity: 0.2; } 50% { opacity: 0.42; } }
@keyframes prs-wobble {
  0%, 100% { transform: rotate(-0.8deg); }
  50%      { transform: rotate(0.8deg); }
}
@keyframes prs-ring {
  0%   { transform: scale(1);   opacity: 0.9; }
  100% { transform: scale(3.2); opacity: 0; }
}
@keyframes prs-swap {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: none; }
}
@keyframes prs-fade { from { opacity: 0; } to { opacity: 1; } }

@media (prefers-reduced-motion: reduce) {
  .prs-card, .prs-card * { animation: none !important; transition: none !important; }
}

options.onInit:
// Sets the text from customProperties
const htmlgraphicsText = htmlNode.getElementById('htmlgraphics-text');

if (htmlgraphicsText) {
  htmlgraphicsText.textContent = customProperties.text;

  // Change the text color based on the theme
  if (theme.isDark) {
    htmlgraphicsText.style.color = 'green';
  } else {
    htmlgraphicsText.style.color = 'red';
  }
}

options.onRender:
const card = htmlNode.querySelector('.prs-card');
if (!card) return;
const $ = (id) => htmlNode.querySelector('#' + id);
const st = card.__prs || (card.__prs = { num: null, raf: null, drawn: false, level: null, init: false });

/* ---------- Settings ---------- */
const DIAL_MIN = 960;                    // barometer dial scale (hPa)
const DIAL_MAX = 1060;
const STD_PRESSURE = 1013.25;            // reference line on the chart
const RATE_WINDOW_MS = 3 * 60 * 60 * 1000; // 3h barometric tendency
const RATE_THRESHOLD = 0.5;              // hPa per 3h needed to leave "Steady"
const STALE_MS = 5 * 60 * 1000;
const MAX_POINTS = 240;
const LOCALE = 'en-US';
const PALETTE = [                        // purple family, base rgb(143, 59, 184)
  [960, '#6b2fa0'], [1013, '#8f3bb8'], [1050, '#b368db']
];
const LEVELS = [                         // classic barometer scale
  { max: 970,      label: 'Stormy' },
  { max: 990,      label: 'Rain' },
  { max: 1010,     label: 'Change' },
  { max: 1030,     label: 'Fair' },
  { max: Infinity, label: 'Very dry' }
];

/* ---------- Helpers ---------- */
const toArr = (v) => {
  if (!v) return [];
  if (Array.isArray(v)) return v;
  if (typeof v.toArray === 'function') return v.toArray();
  if (typeof v.get === 'function') { const a = []; for (let i = 0; i < v.length; i++) a.push(v.get(i)); return a; }
  return Array.from(v);
};
const hexToRgb = (c) => [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16));
const rgbToHex = (a) => '#' + a.map((v) => Math.round(v).toString(16).padStart(2, '0')).join('');
const mix = (c1, c2, k) => { const a = hexToRgb(c1), b = hexToRgb(c2); return rgbToHex(a.map((v, j) => v + (b[j] - v) * k)); };
const colorAt = (t) => {
  if (t <= PALETTE[0][0]) return PALETTE[0][1];
  for (let i = 1; i < PALETTE.length; i++) {
    const [t1, c1] = PALETTE[i];
    if (t <= t1) {
      const [t0, c0] = PALETTE[i - 1];
      return mix(c0, c1, (t - t0) / (t1 - t0));
    }
  }
  return PALETTE[PALETTE.length - 1][1];
};
const lighten = (c, k = 0.38) => mix(c, '#ffffff', k);
const fmt = (v) => v.toLocaleString(LOCALE, { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const fmtTime = (t) => new Date(t).toLocaleTimeString(LOCALE, { hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });

/* ---------- Data ---------- */
let points = [];
let hasTime = false;
for (const s of (data && data.series) || []) {
  const tf = s.fields.find((f) => f.type === 'time');
  const vf = s.fields.find((f) => f.type === 'number');
  if (!vf) continue;
  hasTime = !!tf;
  const ts = tf ? toArr(tf.values) : [];
  toArr(vf.values).forEach((v, i) => {
    if (v !== null && v !== undefined && !isNaN(v) && Number(v) > 300 && Number(v) < 1100) {
      points.push({ t: ts[i] != null ? Number(ts[i]) : i * 60000, v: Number(v) });
    }
  });
  break;
}
points.sort((a, b) => a.t - b.t);

if (!points.length) {
  $('prs-value').textContent = '--';
  $('prs-level').textContent = 'No data in range';
  $('prs-trend').innerHTML = '';
  card.classList.add('is-stale');
  return;
}

/* ---------- Calculations ---------- */
const all = points.map((p) => p.v);
const last = points[points.length - 1];
const cur = last.v;
const pMin = Math.min(...all);
const pMax = Math.max(...all);
const pAvg = all.reduce((a, b) => a + b, 0) / all.length;
const level = LEVELS.find((l) => cur < l.max);
const accent = colorAt(cur);

/* 3h tendency via linear regression (hPa/h * 3) */
const win = points.filter((p) => p.t >= last.t - RATE_WINDOW_MS);
let rate3h = 0;
if (win.length >= 3) {
  const t0 = win[0].t;
  let sx = 0, sy = 0, sxx = 0, sxy = 0;
  win.forEach((p) => {
    const x = (p.t - t0) / 3.6e6;
    sx += x; sy += p.v; sxx += x * x; sxy += x * p.v;
  });
  const n = win.length;
  const den = n * sxx - sx * sx;
  if (den) rate3h = ((n * sxy - sx * sy) / den) * 3;
}
const trend = rate3h > RATE_THRESHOLD ? 'up' : rate3h < -RATE_THRESHOLD ? 'down' : 'flat';

/* ---------- Theme and state ---------- */
card.style.setProperty('--accent', accent);
card.style.setProperty('--accent-hi', lighten(accent));
card.classList.toggle('is-stale', hasTime && Date.now() - last.t > STALE_MS);

/* ---------- Animated value ---------- */
const valEl = $('prs-value');
if (st.num !== cur) {
  const from = st.num ?? DIAL_MIN;
  cancelAnimationFrame(st.raf);
  const t0 = performance.now();
  const dur = 1400;
  const step = (now) => {
    const k = Math.min(1, (now - t0) / dur);
    const e = 1 - Math.pow(1 - k, 3);
    valEl.textContent = fmt(from + (cur - from) * e);
    if (k < 1) st.raf = requestAnimationFrame(step);
  };
  st.raf = requestAnimationFrame(step);
  st.num = cur;
}

/* ---------- Dial ---------- */
const ticks = $('prs-ticks');
if (!ticks.children.length) {
  let s = '';
  for (let i = 0; i <= 20; i++) {
    const th = ((-120 + i * 12) * Math.PI) / 180;
    const major = i % 5 === 0;
    const r1 = major ? 31 : 32.5, r2 = 34.5;
    s += `<line class="${major ? '' : 'minor'}" ` +
      `x1="${(40 + r1 * Math.sin(th)).toFixed(2)}" y1="${(40 - r1 * Math.cos(th)).toFixed(2)}" ` +
      `x2="${(40 + r2 * Math.sin(th)).toFixed(2)}" y2="${(40 - r2 * Math.cos(th)).toFixed(2)}"/>`;
  }
  ticks.innerHTML = s;
}
const needle = $('prs-needle');
const progress = $('prs-progress');
if (!st.init) { needle.getBoundingClientRect(); st.init = true; }
const ratio = Math.max(0, Math.min(1, (cur - DIAL_MIN) / (DIAL_MAX - DIAL_MIN)));
needle.style.transform = `rotate(${(-120 + ratio * 240).toFixed(2)}deg)`;
progress.style.strokeDashoffset = (100 - ratio * 100).toFixed(2);

/* ---------- Level ---------- */
const lvlEl = $('prs-level');
if (st.level !== level.label) {
  lvlEl.textContent = level.label;
  lvlEl.classList.remove('prs-swap');
  void lvlEl.offsetWidth;
  lvlEl.classList.add('prs-swap');
  st.level = level.label;
}

/* ---------- Trend ---------- */
const ICONS = {
  up:   '<svg viewBox="0 0 16 16"><path d="M4 10l4-4 4 4"/></svg>',
  down: '<svg viewBox="0 0 16 16"><path d="M4 6l4 4 4-4"/></svg>',
  flat: '<svg viewBox="0 0 16 16"><path d="M3 8h10"/></svg>'
};
const rateTxt = Math.abs(rate3h).toFixed(1) + ' hPa/3h';
const TEXT = { up: 'Rising +' + rateTxt, down: 'Falling -' + rateTxt, flat: 'Steady' };
const trendEl = $('prs-trend');
trendEl.className = 'prs-trend prs-trend--' + trend;
trendEl.innerHTML = ICONS[trend] + '<span>' + TEXT[trend] + '</span>';

/* ---------- Chips and header ---------- */
$('prs-min').textContent = fmt(pMin);
$('prs-avg').textContent = fmt(pAvg);
$('prs-max').textContent = fmt(pMax);
$('prs-updated').textContent = hasTime ? 'Updated ' + fmtTime(last.t) : '';

/* ---------- Chart ---------- */
const recent = points.slice(-MAX_POINTS);
const vals = recent.map((p) => p.v);

const svg = $('prs-svg');
const w = Math.max(80, svg.clientWidth || 300);
const h = Math.max(60, svg.clientHeight || 100);
svg.setAttribute('viewBox', `0 0 ${w} ${h}`);

let lo = Math.min(...vals), hi = Math.max(...vals);
if (hi - lo < 1) { const mid = (hi + lo) / 2; lo = mid - 0.5; hi = mid + 0.5; }
const padV = (hi - lo) * 0.15;
lo -= padV; hi += padV;

const padL = 40, padR = 6, padT = 16, padB = 16;
const xOf = (i) => vals.length === 1 ? (padL + w) / 2 : padL + (i * (w - padL - padR)) / (vals.length - 1);
const yOf = (v) => h - padB - ((v - lo) / (hi - lo)) * (h - padT - padB);

/* Grid */
const rawStep = (hi - lo) / 3;
const step = [0.1, 0.2, 0.5, 1, 2, 5, 10, 20].find((s) => s >= rawStep) || 20;
const dec = step < 1 ? 1 : 0;
let grid = '';
for (let v = Math.ceil(lo / step) * step; v <= hi + 1e-9; v += step) {
  const y = yOf(v).toFixed(1);
  grid += `<line x1="${padL}" x2="${w - padR}" y1="${y}" y2="${y}"/>`;
  grid += `<text x="0" y="${(Number(y) + 3).toFixed(1)}">${v.toFixed(dec)}</text>`;
}
$('prs-grid').innerHTML = grid;

/* Standard pressure reference */
const ref = $('prs-ref');
if (STD_PRESSURE > lo && STD_PRESSURE < hi) {
  const ry = yOf(STD_PRESSURE);
  const rl = $('prs-ref-line');
  rl.setAttribute('x1', padL);
  rl.setAttribute('x2', w - padR);
  rl.setAttribute('y1', ry.toFixed(1));
  rl.setAttribute('y2', ry.toFixed(1));
  const rt = $('prs-ref-label');
  rt.setAttribute('x', (w - padR - 2).toFixed(1));
  rt.setAttribute('y', (ry - 4).toFixed(1));
  ref.classList.remove('is-hidden');
} else {
  ref.classList.add('is-hidden');
}

/* Line gradient */
const lg = $('prsLineGrad');
lg.setAttribute('y1', yOf(lo).toFixed(1));
lg.setAttribute('y2', yOf(hi).toFixed(1));
let stops = '';
for (let k = 0; k <= 6; k++) {
  const t = lo + ((hi - lo) * k) / 6;
  stops += `<stop offset="${(k / 6).toFixed(3)}" stop-color="${lighten(colorAt(t), 0.15 + 0.3 * (k / 6))}"/>`;
}
lg.innerHTML = stops;

/* Smooth path */
const xy = vals.map((v, i) => [xOf(i), yOf(v)]);
const smooth = (P) => {
  let d = `M${P[0][0].toFixed(1)},${P[0][1].toFixed(1)}`;
  for (let i = 0; i < P.length - 1; i++) {
    const p0 = P[i - 1] || P[i], p1 = P[i], p2 = P[i + 1], p3 = P[i + 2] || p2;
    const t = 1 / 6;
    const c1x = p1[0] + (p2[0] - p0[0]) * t, c1y = p1[1] + (p2[1] - p0[1]) * t;
    const c2x = p2[0] - (p3[0] - p1[0]) * t, c2y = p2[1] - (p3[1] - p1[1]) * t;
    d += ` C${c1x.toFixed(1)},${c1y.toFixed(1)} ${c2x.toFixed(1)},${c2y.toFixed(1)} ${p2[0].toFixed(1)},${p2[1].toFixed(1)}`;
  }
  return d;
};
const lineD = smooth(xy);
const line = $('prs-line');
const area = $('prs-area');
line.setAttribute('d', lineD);
area.setAttribute('d', `${lineD} L${xy[xy.length - 1][0].toFixed(1)},${h - padB} L${xy[0][0].toFixed(1)},${h - padB} Z`);

const [lx, ly] = xy[xy.length - 1];
['prs-dot', 'prs-ring'].forEach((id) => {
  const c = $(id);
  c.setAttribute('cx', lx.toFixed(1));
  c.setAttribute('cy', ly.toFixed(1));
});

/* Min / max markers */
let marks = '';
const iMax = vals.indexOf(Math.max(...vals));
const iMin = vals.indexOf(Math.min(...vals));
if (iMax !== iMin) {
  const clampX = (x) => Math.max(padL + 18, Math.min(w - padR - 18, x));
  const [mxX, mxY] = xy[iMax];
  const [mnX, mnY] = xy[iMin];
  const cMax = lighten(colorAt(vals[iMax]), 0.4);
  const cMin = lighten(colorAt(vals[iMin]), 0.4);
  marks += `<circle cx="${mxX.toFixed(1)}" cy="${mxY.toFixed(1)}" r="3" stroke="${cMax}"/>`;
  marks += `<text x="${clampX(mxX).toFixed(1)}" y="${(mxY - 7).toFixed(1)}" fill="${cMax}">${fmt(vals[iMax])}</text>`;
  marks += `<circle cx="${mnX.toFixed(1)}" cy="${mnY.toFixed(1)}" r="3" stroke="${cMin}"/>`;
  marks += `<text x="${clampX(mnX).toFixed(1)}" y="${(mnY + 14).toFixed(1)}" fill="${cMin}">${fmt(vals[iMin])}</text>`;
}
$('prs-marks').innerHTML = marks;

/* Draw-in animation */
if (!st.drawn) {
  const len = line.getTotalLength();
  line.style.transition = 'none';
  line.style.strokeDasharray = len;
  line.style.strokeDashoffset = len;
  line.getBoundingClientRect();
  line.style.transition = 'stroke-dashoffset 1.8s cubic-bezier(0.4, 0, 0.2, 1)';
  line.style.strokeDashoffset = '0';
  setTimeout(() => {
    line.style.transition = '';
    line.style.strokeDasharray = 'none';
  }, 1900);
  st.drawn = true;
}
area.classList.add('is-visible');

/* X axis */
if (hasTime) {
  $('prs-x0').textContent = fmtTime(recent[0].t);
  $('prs-x1').textContent = fmtTime(recent[Math.floor(recent.length / 2)].t);
  $('prs-x2').textContent = fmtTime(recent[recent.length - 1].t);
} else {
  $('prs-x0').textContent = $('prs-x1').textContent = $('prs-x2').textContent = '';
}

options.css:
.lux-card {
  --accent: #f5c451;
  --glow: 0.5;
  --pct: 0%;
  --bg-1: #0b0f16;
  --bg-2: #151b26;
  --text: #e9edf4;
  --muted: #8892a6;
  --line: rgba(255, 255, 255, 0.07);

  position: relative;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  min-height: 340px;
  padding: 20px 22px 18px;
  border-radius: 18px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 16px;
  color: var(--text);
  font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: linear-gradient(160deg, var(--bg-2) 0%, var(--bg-1) 100%);
  border: 1px solid var(--line);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  animation: lux-enter 0.9s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.lux-card > *:not(.lux-bg) { position: relative; z-index: 1; }

/* Brilho ambiente de fundo */
.lux-bg {
  position: absolute;
  inset: -40%;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 28% 32%, var(--accent) 0%, transparent 38%),
    radial-gradient(circle at 80% 85%, #3b4cff 0%, transparent 40%);
  opacity: calc(0.06 + var(--glow) * 0.16);
  filter: blur(40px);
  transition: opacity 1.2s ease;
  animation: lux-drift 22s ease-in-out infinite alternate;
}

/* Cabeçalho */
.lux-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.lux-title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}
.lux-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 0 var(--accent);
  animation: lux-pulse 2.6s ease-out infinite;
  transition: background 0.8s ease;
}
.lux-card.is-stale .lux-dot {
  background: #5a6273;
  animation: none;
}
.lux-badges { display: flex; gap: 8px; align-items: center; }
.lux-badge {
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.04em;
  padding: 4px 10px;
  border-radius: 999px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
}
.lux-status { color: var(--accent); transition: color 0.8s ease; }
.lux-card.is-stale .lux-status { color: #8a93a5; }

/* Área principal */
.lux-main {
  display: flex;
  align-items: center;
  gap: 22px;
  flex-wrap: wrap;
}
.lux-orb-wrap {
  width: 112px;
  height: 112px;
  flex: 0 0 auto;
}
.lux-orb { width: 100%; height: 100%; overflow: visible; }

.lux-rays {
  transform-box: fill-box;
  transform-origin: center;
  animation: lux-spin 60s linear infinite;
}
.lux-rays line {
  stroke: var(--accent);
  stroke-width: 2.4;
  stroke-linecap: round;
  opacity: calc(0.15 + var(--glow) * 0.7);
  transition: stroke 1s ease, opacity 1s ease;
}
.lux-rays line:nth-child(even) { stroke-width: 1.6; opacity: calc(0.08 + var(--glow) * 0.45); }

.lux-halo {
  fill: var(--accent);
  opacity: calc(0.06 + var(--glow) * 0.14);
  transform-box: fill-box;
  transform-origin: center;
  animation: lux-breathe 4.5s ease-in-out infinite;
  transition: fill 1s ease;
}
.lux-core {
  filter: drop-shadow(0 0 calc(6px + var(--glow) * 22px) var(--accent));
  transition: filter 1s ease;
}
.lux-stop-a { stop-color: #ffffff; }
.lux-stop-b { stop-color: var(--accent); transition: stop-color 1s ease; }

.lux-reading { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.lux-value {
  display: flex;
  align-items: baseline;
  gap: 8px;
  line-height: 1;
}
#lux-value {
  font-size: 58px;
  font-weight: 300;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
  background: linear-gradient(180deg, #ffffff 0%, #c9d1df 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.lux-unit {
  font-size: 18px;
  font-weight: 500;
  color: var(--muted);
}
.lux-level {
  font-size: 15px;
  font-weight: 500;
  color: var(--accent);
  transition: color 0.8s ease;
}
.lux-swap { animation: lux-swap 0.6s cubic-bezier(0.2, 0.8, 0.2, 1); }

.lux-trend {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: fit-content;
  font-size: 12px;
  font-weight: 500;
  padding: 4px 10px 4px 8px;
  border-radius: 999px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
  transition: color 0.5s ease, background 0.5s ease;
}
.lux-trend svg {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.lux-trend--up { color: #f5c451; background: rgba(245, 196, 81, 0.08); }
.lux-trend--down { color: #8f9cff; background: rgba(143, 156, 255, 0.08); }

/* Medidor logarítmico */
.lux-gauge { display: flex; flex-direction: column; gap: 8px; }
.lux-gauge-track {
  position: relative;
  height: 6px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
}
.lux-gauge-fill {
  position: absolute;
  inset: 0;
  border-radius: 999px;
  background: linear-gradient(90deg, #5b6cff, #7c6cff, #a874f0, #e48aa8, #f2a65a, #f5c451, #ffd97a, #fff0c2);
  clip-path: inset(0 calc(100% - var(--pct)) 0 0 round 999px);
  transition: clip-path 1.4s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.lux-gauge-marker {
  position: absolute;
  top: 50%;
  left: var(--pct);
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #ffffff;
  transform: translate(-50%, -50%);
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.08), 0 0 14px var(--accent);
  transition: left 1.4s cubic-bezier(0.2, 0.8, 0.2, 1), box-shadow 1s ease;
}
.lux-gauge-scale {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: var(--muted);
  letter-spacing: 0.04em;
  font-variant-numeric: tabular-nums;
}

/* Gráfico */
.lux-chart {
  flex: 1 1 auto;
  min-height: 70px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.lux-chart-head {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: var(--muted);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
#lux-spark {
  flex: 1 1 auto;
  width: 100%;
  min-height: 56px;
  overflow: visible;
}
#lux-line {
  fill: none;
  stroke: var(--accent);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 0 6px var(--accent));
  transition: stroke 1s ease;
}
#lux-area { opacity: 0; transition: opacity 1.2s ease 0.4s; }
#lux-area.is-visible { opacity: 1; }
.lux-area-a { stop-color: var(--accent); stop-opacity: 0.32; }
.lux-area-b { stop-color: var(--accent); stop-opacity: 0; }
#lux-last { fill: #ffffff; }
#lux-last-ring {
  fill: none;
  stroke: var(--accent);
  stroke-width: 1.5;
  transform-box: fill-box;
  transform-origin: center;
  animation: lux-ring 2.4s ease-out infinite;
}

/* Estatísticas */
.lux-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-top: 1px solid var(--line);
  padding-top: 14px;
}
.lux-stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 0 10px;
  border-left: 1px solid var(--line);
}
.lux-stat:first-child { border-left: none; padding-left: 0; }
.lux-stat-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}
.lux-stat-value {
  font-size: 15px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}
.lux-stat-value small { font-size: 11px; color: var(--muted); margin-left: 2px; }

/* Animações */
@keyframes lux-enter {
  from { opacity: 0; transform: translateY(10px) scale(0.99); }
  to   { opacity: 1; transform: none; }
}
@keyframes lux-drift {
  from { transform: translate(0, 0) rotate(0deg); }
  to   { transform: translate(6%, -4%) rotate(8deg); }
}
@keyframes lux-spin { to { transform: rotate(360deg); } }
@keyframes lux-breathe {
  0%, 100% { transform: scale(1); }
  50%      { transform: scale(1.14); }
}
@keyframes lux-pulse {
  0%   { box-shadow: 0 0 0 0 var(--accent); }
  70%  { box-shadow: 0 0 0 8px transparent; }
  100% { box-shadow: 0 0 0 0 transparent; }
}
@keyframes lux-ring {
  0%   { transform: scale(1); opacity: 0.9; }
  100% { transform: scale(3.2); opacity: 0; }
}
@keyframes lux-swap {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .lux-card *, .lux-card { animation: none !important; transition: none !important; }
}

options.onInit:
// Sets the text from customProperties
const htmlgraphicsText = htmlNode.getElementById('htmlgraphics-text');

if (htmlgraphicsText) {
  htmlgraphicsText.textContent = customProperties.text;

  // Change the text color based on the theme
  if (theme.isDark) {
    htmlgraphicsText.style.color = 'green';
  } else {
    htmlgraphicsText.style.color = 'red';
  }
}

options.onRender:
const card = htmlNode.querySelector('.lux-card');
if (!card) return;
const $ = (id) => htmlNode.querySelector('#' + id);
const st = card.__lux || (card.__lux = { shown: null, raf: null, drawn: false, level: null });

/* ---------- Settings ---------- */
const STALE_MS = 5 * 60 * 1000;   // dot turns gray after 5 min without data
const MAX_POINTS = 60;            // points shown in the chart
const LOCALE = 'en-US';
const LEVELS = [
  { max: 1,        label: 'Darkness',          color: '#5b6cff' },
  { max: 10,       label: 'Very dark',         color: '#7c6cff' },
  { max: 50,       label: 'Dim',               color: '#a874f0' },
  { max: 200,      label: 'Low light',         color: '#e48aa8' },
  { max: 500,      label: 'Indoor lighting',   color: '#f2a65a' },
  { max: 1000,     label: 'Well lit',          color: '#f5c451' },
  { max: 10000,    label: 'Daylight',          color: '#ffd97a' },
  { max: Infinity, label: 'Direct sunlight',   color: '#fff0c2' }
];

/* ---------- Data ---------- */
const toArr = (v) => {
  if (!v) return [];
  if (Array.isArray(v)) return v;
  if (typeof v.toArray === 'function') return v.toArray();
  if (typeof v.get === 'function') { const a = []; for (let i = 0; i < v.length; i++) a.push(v.get(i)); return a; }
  return Array.from(v);
};

let points = [];
for (const s of (data && data.series) || []) {
  const tf = s.fields.find((f) => f.type === 'time');
  const vf = s.fields.find((f) => f.type === 'number');
  if (!vf) continue;
  const ts = tf ? toArr(tf.values) : [];
  toArr(vf.values).forEach((v, i) => {
    if (v !== null && v !== undefined && !isNaN(v)) points.push({ t: ts[i] != null ? Number(ts[i]) : null, v: Number(v) });
  });
  break;
}
points.sort((a, b) => (a.t ?? 0) - (b.t ?? 0));

if (!points.length) {
  $('lux-value').textContent = '--';
  $('lux-level').textContent = 'No data in range';
  $('lux-trend').innerHTML = '';
  card.classList.add('is-stale');
  return;
}

/* ---------- Calculations ---------- */
const values = points.map((p) => p.v);
const last = points[points.length - 1];
const current = last.v;
const min = Math.min(...values);
const max = Math.max(...values);
const avg = values.reduce((a, b) => a + b, 0) / values.length;
const level = LEVELS.find((l) => current < l.max);
const pct = Math.max(0, Math.min(1, Math.log10(current + 1) / 5));

const fmt = (v) => v.toLocaleString(LOCALE, { maximumFractionDigits: Math.abs(v) < 10 ? 1 : 0 });

/* ---------- Dynamic theme ---------- */
card.style.setProperty('--accent', level.color);
card.style.setProperty('--glow', (0.2 + 0.8 * pct).toFixed(3));
card.style.setProperty('--pct', (pct * 100).toFixed(2) + '%');

/* ---------- Animated value ---------- */
const valEl = $('lux-value');
if (st.shown !== current) {
  const from = st.shown ?? 0;
  cancelAnimationFrame(st.raf);
  const t0 = performance.now();
  const dur = 1100;
  const step = (now) => {
    const k = Math.min(1, (now - t0) / dur);
    const e = 1 - Math.pow(1 - k, 3);
    valEl.textContent = fmt(from + (current - from) * e);
    if (k < 1) st.raf = requestAnimationFrame(step);
  };
  st.raf = requestAnimationFrame(step);
  st.shown = current;
}

/* ---------- Level ---------- */
const lvlEl = $('lux-level');
if (st.level !== level.label) {
  lvlEl.textContent = level.label;
  lvlEl.classList.remove('lux-swap');
  void lvlEl.offsetWidth;
  lvlEl.classList.add('lux-swap');
  st.level = level.label;
}

/* ---------- Trend ---------- */
const prev = values.slice(-6, -1);
let trend = 'flat';
let delta = 0;
if (prev.length) {
  const ref = prev.reduce((a, b) => a + b, 0) / prev.length;
  delta = current - ref;
  const thr = Math.max(1, ref * 0.05);
  trend = delta > thr ? 'up' : delta < -thr ? 'down' : 'flat';
}
const ICONS = {
  up:   '<svg viewBox="0 0 16 16"><path d="M4 10l4-4 4 4"/></svg>',
  down: '<svg viewBox="0 0 16 16"><path d="M4 6l4 4 4-4"/></svg>',
  flat: '<svg viewBox="0 0 16 16"><path d="M3 8h10"/></svg>'
};
const TEXT = {
  up: 'Rising +' + fmt(Math.abs(delta)) + ' lx',
  down: 'Falling -' + fmt(Math.abs(delta)) + ' lx',
  flat: 'Stable'
};
const trendEl = $('lux-trend');
trendEl.className = 'lux-trend lux-trend--' + trend;
trendEl.innerHTML = ICONS[trend] + '<span>' + TEXT[trend] + '</span>';

/* ---------- Stats ---------- */
$('lux-min').innerHTML = fmt(min) + '<small>lx</small>';
$('lux-avg').innerHTML = fmt(avg) + '<small>lx</small>';
$('lux-max').innerHTML = fmt(max) + '<small>lx</small>';
$('lux-time').textContent = last.t
  ? new Date(last.t).toLocaleTimeString(LOCALE, { hour: '2-digit', minute: '2-digit', hourCycle: 'h23' })
  : '--';

/* ---------- Stale indicator (gray dot) ---------- */
const stale = last.t ? Date.now() - last.t > STALE_MS : false;
card.classList.toggle('is-stale', stale);

/* ---------- Chart ---------- */
const svg = $('lux-spark');
const w = Math.max(60, svg.clientWidth || 300);
const h = Math.max(40, svg.clientHeight || 70);
svg.setAttribute('viewBox', `0 0 ${w} ${h}`);

const pts = points.slice(-MAX_POINTS);
$('lux-count').textContent = pts.length + (pts.length === 1 ? ' reading' : ' readings');

const pad = 6;
const vmin = Math.min(...pts.map((p) => p.v));
const vmax = Math.max(...pts.map((p) => p.v));
const range = vmax - vmin;
const xy = pts.map((p, i) => [
  pts.length === 1 ? w / 2 : pad + (i * (w - pad * 2)) / (pts.length - 1),
  range === 0 ? h / 2 : h - pad - ((p.v - vmin) / range) * (h - pad * 2)
]);

const smooth = (P) => {
  let d = `M${P[0][0].toFixed(1)},${P[0][1].toFixed(1)}`;
  for (let i = 0; i < P.length - 1; i++) {
    const p0 = P[i - 1] || P[i], p1 = P[i], p2 = P[i + 1], p3 = P[i + 2] || p2;
    const t = 1 / 6;
    const c1x = p1[0] + (p2[0] - p0[0]) * t, c1y = p1[1] + (p2[1] - p0[1]) * t;
    const c2x = p2[0] - (p3[0] - p1[0]) * t, c2y = p2[1] - (p3[1] - p1[1]) * t;
    d += ` C${c1x.toFixed(1)},${c1y.toFixed(1)} ${c2x.toFixed(1)},${c2y.toFixed(1)} ${p2[0].toFixed(1)},${p2[1].toFixed(1)}`;
  }
  return d;
};

const lineD = smooth(xy);
const line = $('lux-line');
const area = $('lux-area');
line.setAttribute('d', lineD);
area.setAttribute('d', `${lineD} L${xy[xy.length - 1][0].toFixed(1)},${h} L${xy[0][0].toFixed(1)},${h} Z`);

const [lx, ly] = xy[xy.length - 1];
['lux-last', 'lux-last-ring'].forEach((id) => {
  const c = $(id);
  c.setAttribute('cx', lx.toFixed(1));
  c.setAttribute('cy', ly.toFixed(1));
});

if (!st.drawn) {
  const len = line.getTotalLength();
  line.style.transition = 'none';
  line.style.strokeDasharray = len;
  line.style.strokeDashoffset = len;
  line.getBoundingClientRect();
  line.style.transition = 'stroke-dashoffset 1.8s cubic-bezier(0.4, 0, 0.2, 1)';
  line.style.strokeDashoffset = '0';
  setTimeout(() => {
    line.style.transition = '';
    line.style.strokeDasharray = 'none';
  }, 1900);
  st.drawn = true;
}
area.classList.add('is-visible');

options.css:
.cpu-wrap {
  width: 100%;
  height: 100%;
}

.cpu-card {
  --accent: #4ade80;
  --accent-hi: #86efac;
  --bg-1: #0b0f16;
  --bg-2: #151b26;
  --text: #e9edf4;
  --muted: #8892a6;
  --line: rgba(255, 255, 255, 0.07);

  position: relative;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  min-height: 140px;
  padding: 12px 14px 12px;
  border-radius: 16px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 6px;
  color: var(--text);
  font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: linear-gradient(160deg, var(--bg-2) 0%, var(--bg-1) 100%);
  border: 1px solid var(--line);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  animation: cpu-enter 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.cpu-card > *:not(.cpu-bg):not(.cpu-spark) { position: relative; z-index: 1; }

.cpu-bg {
  position: absolute;
  inset: -50%;
  z-index: 0;
  pointer-events: none;
  background: radial-gradient(circle at 50% 50%, var(--accent) 0%, transparent 28%);
  opacity: 0.12;
  filter: blur(30px);
  transition: background 1s ease;
}

/* Background sparkline */
.cpu-spark {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 55%;
  z-index: 0;
  pointer-events: none;
  opacity: 0.5;
}
.cpu-spark svg { width: 100%; height: 100%; display: block; }
.cpu-spark-line {
  fill: none;
  stroke: var(--accent);
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: stroke 1s ease;
}
.cpu-spark-area { opacity: 0; transition: opacity 1.2s ease 0.3s; }
.cpu-spark-area.is-visible { opacity: 1; }
.cpu-spark-a { stop-color: var(--accent); stop-opacity: 0.28; transition: stop-color 1s ease; }
.cpu-spark-b { stop-color: var(--accent); stop-opacity: 0; }

/* Header */
.cpu-header { display: flex; align-items: center; }
.cpu-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
}
.cpu-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent);
  animation: cpu-pulse 2.6s ease-out infinite;
  transition: background 0.8s ease;
}
.cpu-card.is-stale .cpu-dot { background: #5a6273; animation: none; }

/* Center ring */
.cpu-center {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.cpu-ring-wrap {
  position: relative;
  height: 100%;
  max-height: 130px;
  aspect-ratio: 1 / 1;
  container-type: size;
}
.cpu-ring { width: 100%; height: 100%; display: block; overflow: visible; }
.cpu-glow {
  fill: var(--accent);
  opacity: 0.18;
  filter: blur(8px);
  transition: fill 1s ease;
  animation: cpu-glow 4s ease-in-out infinite;
}
.cpu-face { fill: rgba(11, 15, 22, 0.55); }
.cpu-spin {
  fill: none;
  stroke: var(--accent);
  stroke-width: 1;
  stroke-dasharray: 1.5 4.5;
  stroke-linecap: round;
  opacity: 0.5;
  transform-box: view-box;
  transform-origin: 32px 32px;
  transition: stroke 1s ease;
}
.cpu-track { fill: none; stroke: rgba(255, 255, 255, 0.07); stroke-width: 4.5; }
.cpu-progress {
  fill: none;
  stroke: var(--accent);
  stroke-width: 4.5;
  stroke-linecap: round;
  stroke-dasharray: 100;
  stroke-dashoffset: 100;
  filter: drop-shadow(0 0 3px var(--accent));
  transition: stroke-dashoffset 1.4s cubic-bezier(0.2, 0.8, 0.2, 1), stroke 1s ease;
}
.cpu-ring-value {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1px;
  line-height: 1;
}
#cpu-value {
  font-size: clamp(16px, 27cqw, 36px);
  font-weight: 400;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
  background: linear-gradient(180deg, #ffffff 0%, #c9d1df 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.cpu-ring-unit {
  font-size: clamp(9px, 11cqw, 14px);
  font-weight: 500;
  color: var(--muted);
  margin-top: 3cqw;
}

/* Bottom level */
.cpu-level {
  text-align: center;
  font-size: 13px;
  font-weight: 500;
  color: var(--accent-hi);
  white-space: nowrap;
  transition: color 0.8s ease;
}
.cpu-swap { animation: cpu-swap 0.6s cubic-bezier(0.2, 0.8, 0.2, 1); }

/* Animations */
@keyframes cpu-enter {
  from { opacity: 0; transform: translateY(8px) scale(0.99); }
  to   { opacity: 1; transform: none; }
}
@keyframes cpu-pulse {
  0%   { box-shadow: 0 0 0 0 var(--accent); }
  70%  { box-shadow: 0 0 0 7px transparent; }
  100% { box-shadow: 0 0 0 0 transparent; }
}
@keyframes cpu-glow { 0%, 100% { opacity: 0.12; } 50% { opacity: 0.28; } }
@keyframes cpu-swap {
  from { opacity: 0; transform: translateY(3px); }
  to   { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .cpu-card, .cpu-card * { animation: none !important; transition: none !important; }
}

