const card = htmlNode.querySelector('.upt-card');
if (!card) return;
const $ = (id) => htmlNode.querySelector('#' + id);
const st = card.__upt || (card.__upt = { timer: null });

/* ---------- Settings ---------- */
const STALE_MS = 5 * 60 * 1000;          // offline after 5 min without data
const RECENT_BOOT_S = 3600;              // amber during the first hour after a reboot
const MAX_POINTS = 240;
const LOCALE = 'en-US';
const COLOR_OK = '#4ade80';
const COLOR_RECENT = '#facc15';

/* ---------- Helpers ---------- */
const toArr = (v) => {
  if (!v) return [];
  if (Array.isArray(v)) return v;
  if (typeof v.toArray === 'function') return v.toArray();
  if (typeof v.get === 'function') { const a = []; for (let i = 0; i < v.length; i++) a.push(v.get(i)); return a; }
  return Array.from(v);
};
const hexToRgb = (c) => [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16));
const rgbToHex = (a) => '#' + a.map((v) => Math.round(v).toString(16).padStart(2, '0')).join('');
const mix = (c1, c2, k) => { const a = hexToRgb(c1), b = hexToRgb(c2); return rgbToHex(a.map((v, j) => v + (b[j] - v) * k)); };
const fmtTime = (t) => new Date(t).toLocaleTimeString(LOCALE, { hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
const fmtDate = (t) => new Date(t).toLocaleString(LOCALE, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });

/* Three most significant units: "6d 13h 25m", "13h 25m 32s", "25m 32s" */
const segments = (secs) => {
  const s = Math.max(0, Math.floor(secs));
  const parts = [
    [Math.floor(s / 86400), 'd'],
    [Math.floor((s % 86400) / 3600), 'h'],
    [Math.floor((s % 3600) / 60), 'm'],
    [s % 60, 's']
  ];
  let start = parts.findIndex(([n]) => n > 0);
  if (start === -1 || start > 2) start = 2;
  return parts.slice(start, start + 3)
    .map(([n, u], i) => `<span class="upt-seg"><span class="upt-n">${i === 0 ? n : String(n).padStart(2, '0')}</span><span class="upt-u">${u}</span></span>`)
    .join('');
};

/* ---------- Data (nulls are skipped) ---------- */
let points = [];
let hasTime = false;
for (const s of (data && data.series) || []) {
  const tf = s.fields.find((f) => f.type === 'time');
  const vf = s.fields.find((f) => f.type === 'number') || s.fields.find((f) => f.type !== 'time');
  if (!vf) continue;
  hasTime = !!tf;
  const ts = tf ? toArr(tf.values) : [];
  toArr(vf.values).forEach((v, i) => {
    if (v === null || v === undefined || v === '') return;
    const n = Number(v);
    if (isNaN(n) || n < 0) return;
    points.push({ t: ts[i] != null ? Number(ts[i]) : i * 60000, v: n });
  });
  break;
}
points.sort((a, b) => a.t - b.t);

clearInterval(st.timer);

if (!points.length) {
  $('upt-value').innerHTML = '<span class="upt-seg"><span class="upt-n">--</span></span>';
  $('upt-foot').innerHTML = '<span class="upt-since">No data in range</span>';
  card.classList.add('is-stale');
  return;
}

/* ---------- Calculations ---------- */
const vals = points.map((p) => p.v);
const last = points[points.length - 1];
const bootTime = last.t - last.v * 1000;

let restarts = 0;
for (let i = 1; i < vals.length; i++) {
  if (vals[i] < vals[i - 1] - 5) restarts++;
}

const accent = last.v < RECENT_BOOT_S ? COLOR_RECENT : COLOR_OK;
card.style.setProperty('--accent', accent);
card.style.setProperty('--accent-hi', mix(accent, '#ffffff', 0.3));

/* ---------- Live counter (ticks every second) ---------- */
const valEl = $('upt-value');
const footEl = $('upt-foot');
const restartTxt = restarts > 0
  ? `<span class="upt-sep">·</span><span class="upt-restarts">${restarts} restart${restarts > 1 ? 's' : ''}</span>`
  : '';

const render = () => {
  if (!card.isConnected) { clearInterval(st.timer); return; }
  const now = Date.now();
  const stale = hasTime && now - last.t > STALE_MS;
  card.classList.toggle('is-stale', stale);

  const live = hasTime && !stale ? last.v + Math.max(0, (now - last.t) / 1000) : last.v;
  valEl.innerHTML = segments(live);

  footEl.innerHTML = stale
    ? `<span class="upt-since">Offline · last seen ${fmtTime(last.t)}</span>`
    : hasTime
      ? `<span class="upt-since">Since ${fmtDate(bootTime)}</span>${restartTxt}`
      : `<span class="upt-since">Running</span>${restartTxt}`;
};
render();
st.timer = setInterval(render, 1000);

/* ---------- Background sparkline ---------- */
// const recent = vals.slice(-MAX_POINTS);
// const svg = $('upt-spark-svg');
// const w = Math.max(60, svg.clientWidth || 300);
// const h = Math.max(20, svg.clientHeight || 60);
// svg.setAttribute('viewBox', `0 0 ${w} ${h}`);

// let lo = Math.min(...recent), hi = Math.max(...recent);
// if (hi - lo < 60) { hi = lo + 60; }
// lo -= (hi - lo) * 0.6;
// const padT = 4;
// const xy = recent.map((v, i) => [
//   recent.length === 1 ? w / 2 : (i * w) / (recent.length - 1),
//   h - ((v - lo) / (hi - lo)) * (h - padT)
// ]);
// let lineD = `M${xy[0][0].toFixed(1)},${xy[0][1].toFixed(1)}`;
// for (let i = 1; i < xy.length; i++) lineD += ` L${xy[i][0].toFixed(1)},${xy[i][1].toFixed(1)}`;
// $('upt-spark-line').setAttribute('d', lineD);
// const area = $('upt-spark-area');
// area.setAttribute('d', `${lineD} L${w},${h} L0,${h} Z`);
