options.css:
.bat-card {
  --accent: #4ade80;
  --volt: #7dd3fc;
  --pct: 0%;
  --bg-1: #0b0f16;
  --bg-2: #151b26;
  --text: #e9edf4;
  --muted: #8892a6;
  --line: rgba(255, 255, 255, 0.07);

  position: relative;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  min-height: 580px;
  padding: 20px 22px 18px;
  border-radius: 18px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 18px;
  color: var(--text);
  font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: linear-gradient(160deg, var(--bg-2) 0%, var(--bg-1) 100%);
  border: 1px solid var(--line);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  animation: bat-enter 0.9s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.bat-card > *:not(.bat-bg) { position: relative; z-index: 1; }

.bat-bg {
  position: absolute;
  inset: -40%;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 26% 22%, var(--accent) 0%, transparent 34%),
    radial-gradient(circle at 78% 82%, var(--volt) 0%, transparent 38%);
  opacity: 0.13;
  filter: blur(40px);
  animation: bat-drift 24s ease-in-out infinite alternate;
}

/* Header */
.bat-header { display: flex; align-items: center; justify-content: space-between; }
.bat-title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}
.bat-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
  animation: bat-pulse 2.6s ease-out infinite;
  transition: background 0.8s ease;
}
.bat-card.is-stale .bat-dot { background: #5a6273; animation: none; }
.bat-badge {
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.04em;
  padding: 4px 10px;
  border-radius: 999px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
}

/* Hero */
.bat-hero { display: flex; align-items: center; gap: 26px; }
.bat-icon-wrap { width: 80px; height: 140px; flex: 0 0 auto; }
.bat-icon { width: 100%; height: 100%; overflow: visible; }

.bat-cap { fill: rgba(255, 255, 255, 0.16); }
.bat-body {
  fill: none;
  stroke: rgba(255, 255, 255, 0.18);
  stroke-width: 2.5;
  transition: stroke 0.8s ease;
}
.bat-card.is-critical .bat-body {
  stroke: var(--accent);
  animation: bat-alert 1.6s ease-in-out infinite;
}
.bat-inner { fill: rgba(255, 255, 255, 0.025); }

.bat-liquid {
  transform: translateY(126px);
  transition: transform 1.8s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.bat-wave--front { animation: bat-wave 3.4s linear infinite; }
.bat-wave--back {
  fill: var(--accent);
  opacity: 0.35;
  animation: bat-wave-rev 5.6s linear infinite;
  transition: fill 0.8s ease;
}
.bat-liq-a { stop-color: var(--accent); stop-opacity: 0.95; transition: stop-color 0.8s ease; }
.bat-liq-b { stop-color: var(--accent); stop-opacity: 0.5; transition: stop-color 0.8s ease; }
.bat-shine { fill: rgba(255, 255, 255, 0.08); }

.bat-bubbles circle { fill: rgba(255, 255, 255, 0.6); opacity: 0; }
.bat-card.is-charging .bat-bubbles circle { animation: bat-rise 3.2s ease-in infinite; }

.bat-bolt {
  fill: #ffffff;
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transform: scale(0.8);
  filter: drop-shadow(0 0 6px rgba(255, 255, 255, 0.55));
  transition: opacity 0.6s ease, transform 0.6s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.bat-card.is-charging .bat-bolt {
  opacity: 0.92;
  transform: scale(1);
  animation: bat-bolt 2.4s ease-in-out infinite;
}

.bat-reading { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.bat-pct { display: flex; align-items: baseline; gap: 4px; line-height: 1; }
#bat-pct {
  font-size: 62px;
  font-weight: 300;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
  background: linear-gradient(180deg, #ffffff 0%, #c9d1df 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.bat-pct-unit { font-size: 22px; font-weight: 500; color: var(--muted); }
.bat-volt {
  font-size: 16px;
  font-weight: 500;
  color: var(--volt);
  font-variant-numeric: tabular-nums;
}
.bat-level {
  font-size: 14px;
  font-weight: 500;
  color: var(--accent);
  transition: color 0.8s ease;
}
.bat-swap { animation: bat-swap 0.6s cubic-bezier(0.2, 0.8, 0.2, 1); }

.bat-trend {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: fit-content;
  margin-top: 2px;
  font-size: 12px;
  font-weight: 500;
  padding: 4px 10px 4px 8px;
  border-radius: 999px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
  transition: color 0.5s ease, background 0.5s ease;
}
.bat-trend svg {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.bat-trend--up { color: #4ade80; background: rgba(74, 222, 128, 0.08); }
.bat-trend--down { color: #f5c451; background: rgba(245, 196, 81, 0.08); }

/* Bars */
.bat-bars { display: flex; flex-direction: column; gap: 16px; }
.bat-bar { display: flex; flex-direction: column; gap: 8px; }
.bat-bar-head { display: flex; justify-content: space-between; align-items: center; }
.bat-bar-label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}
.bat-bar-label svg {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.bat-bar-value { font-size: 13px; font-weight: 500; font-variant-numeric: tabular-nums; }

.bat-vtrack {
  position: relative;
  height: 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
}
.bat-vfill {
  position: absolute;
  inset: 0;
  border-radius: 999px;
  background: linear-gradient(90deg, #f87171, #fb923c, #facc15, #4ade80, #34d399);
  clip-path: inset(0 calc(100% - var(--pct)) 0 0 round 999px);
  transition: clip-path 1.4s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.bat-vmarker {
  position: absolute;
  top: 50%;
  left: var(--pct);
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: #ffffff;
  transform: translate(-50%, -50%);
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.08), 0 0 14px var(--accent);
  transition: left 1.4s cubic-bezier(0.2, 0.8, 0.2, 1), box-shadow 1s ease;
}

.bat-segments {
  display: grid;
  grid-template-columns: repeat(20, 1fr);
  gap: 3px;
  height: 14px;
}
.bat-segments span {
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.06);
  transition:
    background 0.5s ease calc(var(--i) * 35ms),
    box-shadow 0.5s ease calc(var(--i) * 35ms);
}
.bat-segments span.on {
  background: var(--accent);
  box-shadow: 0 0 10px -3px var(--accent);
}
.bat-segments span.edge { animation: bat-edge 2.2s ease-in-out infinite; }

.bat-scale {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: var(--muted);
  letter-spacing: 0.04em;
  font-variant-numeric: tabular-nums;
}

/* Charts */
.bat-charts {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-height: 200px;
}
.bat-chart {
  flex: 1 1 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-height: 90px;
}
.bat-chart-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 11px;
  color: var(--muted);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.bat-chart-title { display: inline-flex; align-items: center; gap: 8px; }
.bat-legend { width: 12px; height: 3px; border-radius: 2px; }
.bat-chart--v .bat-legend { background: var(--volt); }
.bat-chart--p .bat-legend { background: var(--accent); transition: background 0.8s ease; }
.bat-chart-range { font-variant-numeric: tabular-nums; text-transform: none; letter-spacing: 0.02em; }

.bat-svg { flex: 1 1 auto; width: 100%; min-height: 64px; overflow: visible; }
.bat-line {
  fill: none;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.bat-chart--v .bat-line { stroke: var(--volt); filter: drop-shadow(0 0 6px var(--volt)); }
.bat-chart--p .bat-line { stroke: var(--accent); filter: drop-shadow(0 0 6px var(--accent)); transition: stroke 0.8s ease; }

.bat-area { opacity: 0; transition: opacity 1.2s ease 0.4s; }
.bat-area.is-visible { opacity: 1; }
.bat-v-a { stop-color: var(--volt); stop-opacity: 0.3; }
.bat-v-b { stop-color: var(--volt); stop-opacity: 0; }
.bat-p-a { stop-color: var(--accent); stop-opacity: 0.28; }
.bat-p-b { stop-color: var(--accent); stop-opacity: 0; }

.bat-pt { fill: #ffffff; }
.bat-ring {
  fill: none;
  stroke-width: 1.5;
  transform-box: fill-box;
  transform-origin: center;
  animation: bat-ring 2.4s ease-out infinite;
}
.bat-chart--v .bat-ring { stroke: var(--volt); }
.bat-chart--p .bat-ring { stroke: var(--accent); }

.bat-guide { stroke: rgba(248, 113, 113, 0.45); stroke-width: 1; stroke-dasharray: 3 4; }
.bat-guide-label {
  fill: rgba(248, 113, 113, 0.75);
  font-size: 9px;
  font-family: inherit;
  letter-spacing: 0.06em;
}

/* Stats */
.bat-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-top: 1px solid var(--line);
  padding-top: 14px;
}
.bat-stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 0 10px;
  border-left: 1px solid var(--line);
}
.bat-stat:first-child { border-left: none; padding-left: 0; }
.bat-stat-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}
.bat-stat-value { font-size: 15px; font-weight: 500; font-variant-numeric: tabular-nums; }
.bat-stat-value small { font-size: 11px; color: var(--muted); margin-left: 2px; }

/* Animations */
@keyframes bat-enter {
  from { opacity: 0; transform: translateY(10px) scale(0.99); }
  to   { opacity: 1; transform: none; }
}
@keyframes bat-drift {
  from { transform: translate(0, 0) rotate(0deg); }
  to   { transform: translate(5%, -4%) rotate(8deg); }
}
@keyframes bat-pulse {
  0%   { box-shadow: 0 0 0 0 var(--accent); }
  70%  { box-shadow: 0 0 0 8px transparent; }
  100% { box-shadow: 0 0 0 0 transparent; }
}
@keyframes bat-wave     { from { transform: translateX(0); }    to { transform: translateX(52px); } }
@keyframes bat-wave-rev { from { transform: translateX(52px); } to { transform: translateX(0); } }
@keyframes bat-rise {
  0%   { transform: translateY(0);     opacity: 0; }
  20%  { opacity: 0.7; }
  100% { transform: translateY(-90px); opacity: 0; }
}
@keyframes bat-bolt  { 0%, 100% { opacity: 0.92; } 50% { opacity: 0.55; } }
@keyframes bat-alert { 0%, 100% { stroke-opacity: 1; } 50% { stroke-opacity: 0.3; } }
@keyframes bat-edge  { 0%, 100% { opacity: 1; } 50% { opacity: 0.45; } }
@keyframes bat-ring {
  0%   { transform: scale(1);   opacity: 0.9; }
  100% { transform: scale(3.2); opacity: 0; }
}
@keyframes bat-swap {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .bat-card, .bat-card * { animation: none !important; transition: none !important; }
}

/* Time to empty */
.bat-eta {
  display: flex;
  align-items: center;
  gap: 7px;
  max-height: 0;
  opacity: 0;
  overflow: hidden;
  transform: translateY(-4px);
  font-size: 12px;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  transition:
    max-height 0.6s cubic-bezier(0.2, 0.8, 0.2, 1),
    opacity 0.6s ease,
    transform 0.6s cubic-bezier(0.2, 0.8, 0.2, 1),
    margin 0.6s ease;
}
.bat-eta.is-visible {
  max-height: 24px;
  opacity: 1;
  transform: none;
  margin-top: 2px;
}
.bat-eta svg {
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
  fill: none;
  stroke: #f5c451;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.bat-eta-hand {
  transform-origin: 8px 8px;
  animation: bat-eta-tick 6s linear infinite;
}
.bat-eta strong { color: var(--text); font-weight: 600; }
.bat-eta-at { opacity: 0.75; }

@keyframes bat-eta-tick { to { transform: rotate(360deg); } }

options.onInit:
// Sets the text from customProperties
const htmlgraphicsText = htmlNode.getElementById('htmlgraphics-text');

if (htmlgraphicsText) {
  htmlgraphicsText.textContent = customProperties.text;

  // Change the text color based on the theme
  if (theme.isDark) {
    htmlgraphicsText.style.color = 'green';
  } else {
    htmlgraphicsText.style.color = 'red';
  }
}

options.onRender:
const card = htmlNode.querySelector('.bat-card');
if (!card) return;
const $ = (id) => htmlNode.querySelector('#' + id);
const st = card.__bat || (card.__bat = { num: {}, raf: {}, drawn: {}, level: null });

/* ---------- Settings ---------- */
const V_EMPTY = 3.0;                     // 0%
const V_FULL = 4.135;                      // 100%
const LOW_PCT = 20;                      // dashed guide on charge chart
const RATE_WINDOW_MS = 30 * 60 * 1000;   // window used to detect charging / discharging
const RATE_THRESHOLD = 20;               // mV/h needed to leave "Stable"
const STALE_MS = 5 * 60 * 1000;          // dot turns gray after 5 min without data
const MAX_POINTS = 120;                  // points shown in each chart
const SEGMENTS = 20;
const LOCALE = 'en-US';
const LEVELS = [
  { min: 90,        label: 'Full',     color: '#34d399' },
  { min: 60,        label: 'Good',     color: '#4ade80' },
  { min: 35,        label: 'Moderate', color: '#facc15' },
  { min: 15,        label: 'Low',      color: '#fb923c' },
  { min: -Infinity, label: 'Critical', color: '#f87171' }
];

/* ---------- Data ---------- */
const toArr = (v) => {
  if (!v) return [];
  if (Array.isArray(v)) return v;
  if (typeof v.toArray === 'function') return v.toArray();
  if (typeof v.get === 'function') { const a = []; for (let i = 0; i < v.length; i++) a.push(v.get(i)); return a; }
  return Array.from(v);
};

let points = [];
let hasTime = false;
for (const s of (data && data.series) || []) {
  const tf = s.fields.find((f) => f.type === 'time');
  const vf = s.fields.find((f) => f.type === 'number');
  if (!vf) continue;
  hasTime = !!tf;
  const ts = tf ? toArr(tf.values) : [];
  toArr(vf.values).forEach((v, i) => {
    if (v !== null && v !== undefined && !isNaN(v) && Number(v) > 2.5) {
      points.push({ t: ts[i] != null ? Number(ts[i]) : i * 60000, v: Number(v) });
    }
  });
  break;
}
points.sort((a, b) => a.t - b.t);

if (!points.length) {
  $('bat-pct').textContent = '--';
  $('bat-volt').textContent = '--';
  $('bat-level').textContent = 'No data in range';
  $('bat-trend').innerHTML = '';
  card.classList.add('is-stale');
  return;
}

/* ---------- Calculations ---------- */
const toPct = (v) => Math.max(0, Math.min(100, ((v - V_EMPTY) / (V_FULL - V_EMPTY)) * 100));
const volts = points.map((p) => p.v);
const last = points[points.length - 1];
const voltage = last.v;
const pct = toPct(voltage);
const vMin = Math.min(...volts);
const vMax = Math.max(...volts);
const level = LEVELS.find((l) => pct >= l.min);

const fmtV = (v) => v.toLocaleString(LOCALE, { minimumFractionDigits: 3, maximumFractionDigits: 3 });
const fmtP = (v) => Math.round(v).toLocaleString(LOCALE);

/* Rate in mV/h via linear regression over the recent window */
const win = points.filter((p) => p.t >= last.t - RATE_WINDOW_MS);
let rate = 0;
if (win.length >= 3) {
  const t0 = win[0].t;
  let sx = 0, sy = 0, sxx = 0, sxy = 0;
  win.forEach((p) => {
    const x = (p.t - t0) / 3.6e6;
    const y = p.v * 1000;
    sx += x; sy += y; sxx += x * x; sxy += x * y;
  });
  const n = win.length;
  const den = n * sxx - sx * sx;
  if (den) rate = (n * sxy - sx * sy) / den;
}
const trend = rate > RATE_THRESHOLD ? 'up' : rate < -RATE_THRESHOLD ? 'down' : 'flat';

/* ---------- Theme and state ---------- */
card.style.setProperty('--accent', level.color);
card.style.setProperty('--pct', pct.toFixed(2) + '%');
card.classList.toggle('is-charging', trend === 'up');
card.classList.toggle('is-critical', level.label === 'Critical');
card.classList.toggle('is-stale', hasTime && Date.now() - last.t > STALE_MS);

/* ---------- Animated numbers ---------- */
const animateNum = (key, el, to, format, fromDefault) => {
  if (st.num[key] === to) return;
  const from = st.num[key] ?? fromDefault;
  cancelAnimationFrame(st.raf[key]);
  const t0 = performance.now();
  const dur = 1200;
  const step = (now) => {
    const k = Math.min(1, (now - t0) / dur);
    const e = 1 - Math.pow(1 - k, 3);
    el.textContent = format(from + (to - from) * e);
    if (k < 1) st.raf[key] = requestAnimationFrame(step);
  };
  st.raf[key] = requestAnimationFrame(step);
  st.num[key] = to;
};
animateNum('pct', $('bat-pct'), pct, fmtP, 0);
animateNum('volt', $('bat-volt'), voltage, fmtV, V_EMPTY);

/* ---------- Battery liquid ---------- */
const liquid = $('bat-liquid');
if (!st.liquidInit) { liquid.getBoundingClientRect(); st.liquidInit = true; }
liquid.style.transform = `translateY(${(20 + 106 * (1 - pct / 100)).toFixed(2)}px)`;

/* ---------- Level ---------- */
const lvlEl = $('bat-level');
if (st.level !== level.label) {
  lvlEl.textContent = level.label;
  lvlEl.classList.remove('bat-swap');
  void lvlEl.offsetWidth;
  lvlEl.classList.add('bat-swap');
  st.level = level.label;
}

/* ---------- Trend ---------- */
const ICONS = {
  up:   '<svg viewBox="0 0 16 16"><path d="M9 1.5L3.5 9h4l-1 5.5L12 7H8z"/></svg>',
  down: '<svg viewBox="0 0 16 16"><path d="M4 6l4 4 4-4"/></svg>',
  flat: '<svg viewBox="0 0 16 16"><path d="M3 8h10"/></svg>'
};
const rateTxt = Math.abs(rate).toFixed(Math.abs(rate) < 10 ? 1 : 0) + ' mV/h';
const TEXT = {
  up: 'Charging +' + rateTxt,
  down: 'Discharging -' + rateTxt,
  flat: 'Stable'
};
const trendEl = $('bat-trend');
trendEl.className = 'bat-trend bat-trend--' + trend;
trendEl.innerHTML = ICONS[trend] + '<span>' + TEXT[trend] + '</span>';

/* ---------- Time to empty ---------- */
const ETA_WINDOW_MS = 2 * 60 * 60 * 1000;   // longer window for a steadier estimate
const ETA_MIN_POINTS = 10;
const ETA_MAX_DAYS = 30;

const slopeOver = (ms) => {
  const pts = points.filter((p) => p.t >= last.t - ms);
  if (pts.length < ETA_MIN_POINTS) return null;
  const t0 = pts[0].t;
  let sx = 0, sy = 0, sxx = 0, sxy = 0;
  pts.forEach((p) => {
    const x = (p.t - t0) / 3.6e6;
    const y = p.v * 1000;
    sx += x; sy += y; sxx += x * x; sxy += x * y;
  });
  const n = pts.length;
  const den = n * sxx - sx * sx;
  return den ? (n * sxy - sx * sy) / den : null;
};

const fmtDuration = (hours) => {
  const totalMin = Math.round(hours * 60);
  const d = Math.floor(totalMin / 1440);
  const h = Math.floor((totalMin % 1440) / 60);
  const m = totalMin % 60;
  if (d > 0) return `${d}d ${h}h`;
  if (h > 0) return `${h}h ${String(m).padStart(2, '0')}m`;
  return `${Math.max(1, m)} min`;
};

const etaEl = $('bat-eta');
const longRate = slopeOver(ETA_WINDOW_MS);
const etaRate = longRate !== null && longRate < 0 ? longRate : rate;
const showEta = trend === 'down' && etaRate < 0 && voltage > V_EMPTY;

if (showEta) {
  const hoursLeft = ((voltage - V_EMPTY) * 1000) / -etaRate;
  const clock =
    '<svg viewBox="0 0 16 16"><circle cx="8" cy="8" r="6.2"/>' +
    '<path class="bat-eta-hand" d="M8 8V4.6"/><path d="M8 8l2.2 1.4"/></svg>';

  if (hoursLeft / 24 > ETA_MAX_DAYS) {
    etaEl.innerHTML = clock + `<span>Empty in</span><strong>&gt; ${ETA_MAX_DAYS} days</strong>`;
  } else {
    const emptyAt = new Date(last.t + hoursLeft * 3.6e6);
    const atTxt = hoursLeft < 24
      ? emptyAt.toLocaleTimeString(LOCALE, { hour: '2-digit', minute: '2-digit', hourCycle: 'h23' })
      : emptyAt.toLocaleString(LOCALE, { weekday: 'short', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
    etaEl.innerHTML = clock +
      `<span>Empty in</span><strong>${fmtDuration(hoursLeft)}</strong>` +
      `<span class="bat-eta-at">· ~${atTxt}</span>`;
  }
}
etaEl.classList.toggle('is-visible', showEta);

/* ---------- Bars ---------- */
$('bat-vbar-value').textContent = fmtV(voltage) + ' V';
$('bat-pbar-value').textContent = fmtP(pct) + '%';

const segWrap = $('bat-segments');
if (!segWrap.children.length) {
  for (let i = 0; i < SEGMENTS; i++) {
    const s = document.createElement('span');
    s.style.setProperty('--i', i);
    segWrap.appendChild(s);
  }
}
const lit = Math.max(pct > 0 ? 1 : 0, Math.round(pct / (100 / SEGMENTS)));
Array.from(segWrap.children).forEach((s, i) => {
  s.classList.toggle('on', i < lit);
  s.classList.toggle('edge', i === lit - 1);
});

/* ---------- Charts ---------- */
const smooth = (P) => {
  let d = `M${P[0][0].toFixed(1)},${P[0][1].toFixed(1)}`;
  for (let i = 0; i < P.length - 1; i++) {
    const p0 = P[i - 1] || P[i], p1 = P[i], p2 = P[i + 1], p3 = P[i + 2] || p2;
    const t = 1 / 6;
    const c1x = p1[0] + (p2[0] - p0[0]) * t, c1y = p1[1] + (p2[1] - p0[1]) * t;
    const c2x = p2[0] - (p3[0] - p1[0]) * t, c2y = p2[1] - (p3[1] - p1[1]) * t;
    d += ` C${c1x.toFixed(1)},${c1y.toFixed(1)} ${c2x.toFixed(1)},${c2y.toFixed(1)} ${p2[0].toFixed(1)},${p2[1].toFixed(1)}`;
  }
  return d;
};

const drawChart = (key, vals, lo, hi) => {
  const svg = $(`bat-${key}-svg`);
  const w = Math.max(60, svg.clientWidth || 300);
  const h = Math.max(40, svg.clientHeight || 80);
  svg.setAttribute('viewBox', `0 0 ${w} ${h}`);
  const padX = 4, padY = 6;
  const span = hi - lo || 1;
  const yOf = (v) => h - padY - ((v - lo) / span) * (h - padY * 2);
  const xy = vals.map((v, i) => [
    vals.length === 1 ? w / 2 : padX + (i * (w - padX * 2)) / (vals.length - 1),
    yOf(v)
  ]);

  const lineD = smooth(xy);
  const line = $(`bat-${key}-line`);
  const area = $(`bat-${key}-area`);
  line.setAttribute('d', lineD);
  area.setAttribute('d', `${lineD} L${xy[xy.length - 1][0].toFixed(1)},${h} L${xy[0][0].toFixed(1)},${h} Z`);

  const [lx, ly] = xy[xy.length - 1];
  [`bat-${key}-dot`, `bat-${key}-ring`].forEach((id) => {
    const c = $(id);
    c.setAttribute('cx', lx.toFixed(1));
    c.setAttribute('cy', ly.toFixed(1));
  });

  if (!st.drawn[key]) {
    const len = line.getTotalLength();
    line.style.transition = 'none';
    line.style.strokeDasharray = len;
    line.style.strokeDashoffset = len;
    line.getBoundingClientRect();
    line.style.transition = 'stroke-dashoffset 1.8s cubic-bezier(0.4, 0, 0.2, 1)';
    line.style.strokeDashoffset = '0';
    setTimeout(() => {
      line.style.transition = '';
      line.style.strokeDasharray = 'none';
    }, 1900);
    st.drawn[key] = true;
  }
  area.classList.add('is-visible');
  return { w, yOf };
};

const recent = points.slice(-MAX_POINTS);
const rv = recent.map((p) => p.v);

/* Voltage chart: auto-scaled to show small variations */
let lo = Math.min(...rv), hi = Math.max(...rv);
const MIN_SPAN = 0.01;
if (hi - lo < MIN_SPAN) { const mid = (hi + lo) / 2; lo = mid - MIN_SPAN / 2; hi = mid + MIN_SPAN / 2; }
const padV = (hi - lo) * 0.12;
drawChart('v', rv, lo - padV, hi + padV);
$('bat-v-range').textContent = `${fmtV(Math.min(...rv))} – ${fmtV(Math.max(...rv))} V`;

/* Charge chart: fixed 0–100% scale with low-charge guide */
const pc = drawChart('p', rv.map(toPct), 0, 100);
const gy = pc.yOf(LOW_PCT);
const guide = $('bat-p-guide');
guide.setAttribute('x1', 0);
guide.setAttribute('x2', pc.w);
guide.setAttribute('y1', gy.toFixed(1));
guide.setAttribute('y2', gy.toFixed(1));
const gl = $('bat-p-guide-label');
gl.setAttribute('x', (pc.w - 2).toFixed(1));
gl.setAttribute('y', (gy - 4).toFixed(1));
gl.textContent = 'LOW ' + LOW_PCT + '%';

/* ---------- Stats ---------- */
$('bat-min').innerHTML = fmtV(vMin) + '<small>V</small>';
$('bat-max').innerHTML = fmtV(vMax) + '<small>V</small>';
$('bat-rate').innerHTML = (rate >= 0 ? '+' : '-') + Math.abs(rate).toFixed(Math.abs(rate) < 10 ? 1 : 0) + '<small>mV/h</small>';
$('bat-time').textContent = hasTime
  ? new Date(last.t).toLocaleTimeString(LOCALE, { hour: '2-digit', minute: '2-digit', hourCycle: 'h23' })
  : '--';

options.css:
.pwr-card {
  --accent: #fbbf24;
  --accent-hi: #fde68a;
  --sun: 1;
  --sweep: 5s;
  --pct: 0%;
  --tick: 50%;
  --zone-l: 0%;
  --zone-w: 0%;
  --bg-1: #0b0f16;
  --bg-2: #161a24;
  --text: #e9edf4;
  --muted: #8892a6;
  --line: rgba(255, 255, 255, 0.07);

  position: relative;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  min-height: 470px;
  padding: 20px 22px 18px;
  border-radius: 18px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 18px;
  color: var(--text);
  font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: linear-gradient(160deg, var(--bg-2) 0%, var(--bg-1) 100%);
  border: 1px solid var(--line);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  animation: pwr-enter 0.9s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.pwr-card > *:not(.pwr-bg) { position: relative; z-index: 1; }

.pwr-bg {
  position: absolute;
  inset: -40%;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 22% 26%, var(--accent) 0%, transparent 32%),
    radial-gradient(circle at 82% 84%, var(--accent) 0%, transparent 30%);
  opacity: 0.12;
  filter: blur(40px);
  transition: background 1s ease;
  animation: pwr-drift 24s ease-in-out infinite alternate;
}

/* Header + switch */
.pwr-header { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.pwr-title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
}
.pwr-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
  animation: pwr-pulse 2.6s ease-out infinite;
  transition: background 0.8s ease;
}
.pwr-card.is-stale .pwr-dot { background: #5a6273; animation: none; }

.pwr-switch {
  position: relative;
  display: inline-flex;
  padding: 3px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
}
.pwr-switch-pill {
  position: absolute;
  top: 3px;
  left: 3px;
  width: calc(50% - 3px);
  height: calc(100% - 6px);
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 22%, transparent);
  border: 1px solid color-mix(in srgb, var(--accent) 45%, transparent);
  box-shadow: 0 0 14px -4px var(--accent);
  transition: transform 0.55s cubic-bezier(0.2, 0.8, 0.2, 1), background 0.8s ease, border-color 0.8s ease;
}
.pwr-card[data-mode="psu"] .pwr-switch-pill { transform: translateX(100%); }
.pwr-opt {
  position: relative;
  z-index: 1;
  flex: 1 1 0;
  min-width: 78px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 5px 12px;
  border: 0;
  background: none;
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--muted);
  transition: color 0.4s ease;
}
.pwr-opt:hover { color: #c3cad8; }
.pwr-opt.is-active { color: var(--text); }
.pwr-opt svg {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* Hero */
.pwr-hero { display: flex; align-items: center; gap: 24px; flex-wrap: wrap; }
.pwr-art { position: relative; width: 150px; height: 118px; flex: 0 0 auto; }
.pwr-art svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  transition: opacity 0.6s ease, transform 0.6s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.pwr-art-psu { opacity: 0; transform: scale(0.9) translateY(6px); pointer-events: none; }
.pwr-card[data-mode="psu"] .pwr-art-solar { opacity: 0; transform: scale(0.9) translateY(6px); }
.pwr-card[data-mode="psu"] .pwr-art-psu { opacity: 1; transform: none; }

/* Solar art */
.pwr-sun, .pwr-moon { transition: opacity 1s ease; }
.pwr-card.is-night .pwr-sun { opacity: 0; }
.pwr-moon { opacity: 0; }
.pwr-card.is-night .pwr-moon { opacity: 0.85; }
.pwr-moon circle { fill: #cbd5e1; }
.pwr-sun-rays {
  transform-box: view-box;
  transform-origin: 112px 26px;
  animation: pwr-spin 50s linear infinite;
}
.pwr-sun-rays line {
  stroke: #fbbf24;
  stroke-width: 2;
  stroke-linecap: round;
  opacity: calc(0.15 + var(--sun) * 0.75);
  transition: opacity 1s ease;
}
.pwr-sun-core {
  opacity: calc(0.35 + var(--sun) * 0.65);
  filter: drop-shadow(0 0 calc(3px + var(--sun) * 12px) #fbbf24);
  transition: opacity 1s ease, filter 1s ease;
}
.pwr-beam {
  fill: none;
  stroke: #fde68a;
  stroke-width: 1.2;
  stroke-linecap: round;
  stroke-dasharray: 2 5;
  opacity: calc(var(--sun) * 0.65);
  animation: pwr-beam 1.4s linear infinite;
  transition: opacity 1s ease;
}
.pwr-frame { fill: #0d1526; stroke: rgba(255, 255, 255, 0.28); stroke-width: 1.3; stroke-linejoin: round; }
.pwr-cells polygon { fill: url(#pwrCellGrad); stroke: rgba(140, 180, 255, 0.18); stroke-width: 0.5; }
.pwr-shine {
  opacity: calc(var(--sun) * 0.9);
  animation: pwr-sweep var(--sweep) ease-in-out infinite;
  transition: opacity 1s ease;
}
.pwr-card.is-night .pwr-shine { animation: none; opacity: 0; }
.pwr-stand { fill: none; stroke: rgba(255, 255, 255, 0.22); stroke-width: 2; stroke-linecap: round; }

/* PSU art */
.pwr-psu-glow { fill: var(--accent); opacity: 0.18; filter: blur(12px); transition: fill 1s ease; }
.pwr-brick { fill: rgba(255, 255, 255, 0.04); stroke: rgba(255, 255, 255, 0.24); stroke-width: 1.4; }
.pwr-prong { fill: rgba(255, 255, 255, 0.3); }
.pwr-brick-bolt {
  fill: var(--accent);
  filter: drop-shadow(0 0 5px var(--accent));
  transition: fill 1s ease;
}
.pwr-led { fill: var(--accent); animation: pwr-led 2.4s ease-in-out infinite; transition: fill 1s ease; }
.pwr-cable { fill: none; stroke: rgba(255, 255, 255, 0.16); stroke-width: 3.2; stroke-linecap: round; }
.pwr-flow {
  fill: none;
  stroke: var(--accent);
  stroke-width: 3.2;
  stroke-linecap: round;
  stroke-dasharray: 1.5 7;
  filter: drop-shadow(0 0 3px var(--accent));
  animation: pwr-flow 0.9s linear infinite;
  transition: stroke 1s ease, opacity 0.6s ease;
}
.pwr-plug { fill: rgba(255, 255, 255, 0.06); stroke: rgba(255, 255, 255, 0.26); stroke-width: 1.3; }
.pwr-plug-tip { fill: rgba(255, 255, 255, 0.32); }
.pwr-card.is-off .pwr-flow { animation: none; opacity: 0; }
.pwr-card.is-off .pwr-led { animation: none; opacity: 0.25; }
.pwr-card.is-off .pwr-brick-bolt { opacity: 0.35; filter: none; }

/* Reading */
.pwr-reading { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.pwr-value { display: flex; align-items: baseline; gap: 6px; line-height: 1; }
#pwr-value {
  font-size: 58px;
  font-weight: 300;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
  background: linear-gradient(180deg, #ffffff 0%, #c9d1df 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.pwr-unit { font-size: 22px; font-weight: 500; color: var(--muted); }
.pwr-level { font-size: 15px; font-weight: 500; color: var(--accent-hi); transition: color 0.8s ease; }
.pwr-swap { animation: pwr-swap 0.6s cubic-bezier(0.2, 0.8, 0.2, 1); }

.pwr-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: fit-content;
  margin-top: 2px;
  font-size: 12px;
  font-weight: 500;
  padding: 4px 10px 4px 8px;
  border-radius: 999px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
  transition: color 0.5s ease, background 0.5s ease;
}
.pwr-pill svg {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.pwr-pill--ok { color: #4ade80; background: rgba(74, 222, 128, 0.08); }
.pwr-pill--warn { color: #facc15; background: rgba(250, 204, 21, 0.08); }
.pwr-pill--off { color: #94a3b8; }
.pwr-pill--bad { color: #f87171; background: rgba(248, 113, 113, 0.08); }

/* Bar */
.pwr-bar { display: flex; flex-direction: column; gap: 8px; }
.pwr-bar-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; }
.pwr-bar-label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}
.pwr-bar-label svg {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.pwr-bar-value { font-size: 13px; font-weight: 500; font-variant-numeric: tabular-nums; }

.pwr-track {
  position: relative;
  height: 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
}
.pwr-zone {
  position: absolute;
  top: -4px;
  bottom: -4px;
  left: var(--zone-l);
  width: var(--zone-w);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px dashed rgba(255, 255, 255, 0.14);
  transition: left 0.8s ease, width 0.8s ease;
}
.pwr-fill {
  position: absolute;
  inset: 0;
  border-radius: 999px;
  clip-path: inset(0 calc(100% - var(--pct)) 0 0 round 999px);
  transition: clip-path 1.4s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.pwr-card[data-mode="solar"] .pwr-fill {
  background: linear-gradient(90deg, #334155 0%, #64748b 35%, #f59e0b 55%, #facc15 80%, #fde047 100%);
}
.pwr-card[data-mode="psu"] .pwr-fill {
  background: linear-gradient(90deg, #fb923c 0%, #38bdf8 37.5%, #38bdf8 62.5%, #f87171 100%);
}
.pwr-tick {
  position: absolute;
  top: -5px;
  bottom: -5px;
  left: var(--tick);
  width: 2px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.55);
  transform: translateX(-50%);
  transition: left 0.8s ease;
}
.pwr-tick::after {
  content: attr(data-label);
  position: absolute;
  bottom: calc(100% + 3px);
  left: 50%;
  transform: translateX(-50%);
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.06em;
  color: #c3cad8;
  white-space: nowrap;
}
.pwr-marker {
  position: absolute;
  top: 50%;
  left: var(--pct);
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: #ffffff;
  transform: translate(-50%, -50%);
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.08), 0 0 14px var(--accent);
  transition: left 1.4s cubic-bezier(0.2, 0.8, 0.2, 1), box-shadow 1s ease;
}
.pwr-scale {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: var(--muted);
  letter-spacing: 0.04em;
  font-variant-numeric: tabular-nums;
}

/* Chart */
.pwr-chart {
  flex: 1 1 auto;
  min-height: 110px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.pwr-chart-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 11px;
  color: var(--muted);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.pwr-chart-title { display: inline-flex; align-items: center; gap: 8px; }
.pwr-legend { width: 12px; height: 3px; border-radius: 2px; background: var(--accent); transition: background 0.8s ease; }
.pwr-range { font-variant-numeric: tabular-nums; text-transform: none; letter-spacing: 0.02em; }

.pwr-svg { flex: 1 1 auto; width: 100%; min-height: 80px; overflow: visible; }
.pwr-line {
  fill: none;
  stroke: var(--accent);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 0 6px var(--accent));
  transition: stroke 0.8s ease;
}
.pwr-area { opacity: 0; transition: opacity 1.2s ease 0.4s; }
.pwr-area.is-visible { opacity: 1; }
.pwr-area-a { stop-color: var(--accent); stop-opacity: 0.26; transition: stop-color 0.8s ease; }
.pwr-area-b { stop-color: var(--accent); stop-opacity: 0; }
.pwr-pt { fill: #ffffff; }
.pwr-ring {
  fill: none;
  stroke: var(--accent);
  stroke-width: 1.5;
  transform-box: fill-box;
  transform-origin: center;
  animation: pwr-ring 2.4s ease-out infinite;
}
.pwr-ref { transition: opacity 0.6s ease; }
.pwr-ref-band { fill: rgba(56, 189, 248, 0.08); }
.pwr-ref-line { stroke: rgba(255, 255, 255, 0.32); stroke-width: 1; stroke-dasharray: 3 4; }
.pwr-ref-label {
  fill: rgba(255, 255, 255, 0.55);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.1em;
  font-family: inherit;
}

/* Stats */
.pwr-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-top: 1px solid var(--line);
  padding-top: 14px;
}
.pwr-stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 0 10px;
  border-left: 1px solid var(--line);
  min-width: 0;
}
.pwr-stat:first-child { border-left: none; padding-left: 0; }
.pwr-stat-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
}
.pwr-stat-value { font-size: 15px; font-weight: 500; font-variant-numeric: tabular-nums; white-space: nowrap; }
.pwr-stat-value small { font-size: 11px; color: var(--muted); margin-left: 2px; }

/* Mode switch transition */
.pwr-card.is-switching .pwr-reading { animation: pwr-swap 0.6s cubic-bezier(0.2, 0.8, 0.2, 1) both; }
.pwr-card.is-switching .pwr-bar     { animation: pwr-swap 0.6s cubic-bezier(0.2, 0.8, 0.2, 1) 0.06s both; }
.pwr-card.is-switching .pwr-chart   { animation: pwr-swap 0.6s cubic-bezier(0.2, 0.8, 0.2, 1) 0.12s both; }
.pwr-card.is-switching .pwr-stats   { animation: pwr-swap 0.6s cubic-bezier(0.2, 0.8, 0.2, 1) 0.18s both; }

/* Animations */
@keyframes pwr-enter {
  from { opacity: 0; transform: translateY(10px) scale(0.99); }
  to   { opacity: 1; transform: none; }
}
@keyframes pwr-drift {
  from { transform: translate(0, 0) rotate(0deg); }
  to   { transform: translate(5%, -4%) rotate(8deg); }
}
@keyframes pwr-pulse {
  0%   { box-shadow: 0 0 0 0 var(--accent); }
  70%  { box-shadow: 0 0 0 8px transparent; }
  100% { box-shadow: 0 0 0 0 transparent; }
}
@keyframes pwr-spin { to { transform: rotate(360deg); } }
@keyframes pwr-beam { to { stroke-dashoffset: -14; } }
@keyframes pwr-sweep {
  0%   { transform: translateX(-20px); }
  60%  { transform: translateX(190px); }
  100% { transform: translateX(190px); }
}
@keyframes pwr-flow { to { stroke-dashoffset: -17; } }
@keyframes pwr-led { 0%, 100% { opacity: 1; } 50% { opacity: 0.4; } }
@keyframes pwr-ring {
  0%   { transform: scale(1);   opacity: 0.9; }
  100% { transform: scale(3.2); opacity: 0; }
}
@keyframes pwr-swap {
  from { opacity: 0; transform: translateY(6px); }
  to   { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .pwr-card, .pwr-card * { animation: none !important; transition: none !important; }
}

options.onInit:
// Sets the text from customProperties
const htmlgraphicsText = htmlNode.getElementById('htmlgraphics-text');

if (htmlgraphicsText) {
  htmlgraphicsText.textContent = customProperties.text;

  // Change the text color based on the theme
  if (theme.isDark) {
    htmlgraphicsText.style.color = 'green';
  } else {
    htmlgraphicsText.style.color = 'red';
  }
}

options.onRender:
const card = htmlNode.querySelector('.pwr-card');
if (!card) return;
const $ = (id) => htmlNode.querySelector('#' + id);
const STORE_KEY = 'pwr-card-mode';
const st = card.__pwr || (card.__pwr = { num: null, raf: null, drawn: false, bound: false, mode: null, level: null, init: false });

if (!st.mode) {
  let m = 'solar';
  try { m = localStorage.getItem(STORE_KEY) || 'solar'; } catch (e) {}
  st.mode = m === 'psu' ? 'psu' : 'solar';
}

/* ---------- Settings ---------- */
const SOLAR = { min: 0, max: 7.5, chargerMin: 4.0, chargerOk: 4.3, nightBelow: 1.0 };
const PSU = { min: 4.0, max: 6.0, nominal: 5.0, specLo: 4.75, specHi: 5.25, offBelow: 1.0 };
const STALE_MS = 5 * 60 * 1000;
const RIPPLE_WINDOW_MS = 30 * 60 * 1000;
const GAP_MS = 10 * 60 * 1000;          // gaps longer than this don't count as charge time
const MAX_POINTS = 240;
const LOCALE = 'en-US';
const SOLAR_LEVELS = [
  { max: 1.0,      label: 'Night',       color: '#64748b' },
  { max: 4.0,      label: 'Low light',   color: '#a8a29e' },
  { max: 4.6,      label: 'Weak sun',    color: '#f59e0b' },
  { max: 5.6,      label: 'Partial sun', color: '#fbbf24' },
  { max: 6.3,      label: 'Good sun',    color: '#facc15' },
  { max: Infinity, label: 'Full sun',    color: '#fde047' }
];
const PSU_LEVELS = [
  { max: 1.0,      label: 'Disconnected', color: '#f87171' },
  { max: 4.75,     label: 'Undervoltage', color: '#fb923c' },
  { max: 5.25,     label: 'Stable',       color: '#38bdf8' },
  { max: 5.6,      label: 'High',         color: '#facc15' },
  { max: Infinity, label: 'Overvoltage',  color: '#f87171' }
];
const ICONS = {
  bolt:  '<svg viewBox="0 0 16 16"><path d="M9 1.5L3.5 9h4l-1 5.5L12 7H8z"/></svg>',
  check: '<svg viewBox="0 0 16 16"><path d="M3.5 8.5l3 3 6-7"/></svg>',
  alert: '<svg viewBox="0 0 16 16"><path d="M8 3.5v5.5M8 12v.5"/></svg>',
  off:   '<svg viewBox="0 0 16 16"><path d="M3 8h10"/></svg>'
};

/* ---------- Helpers ---------- */
const toArr = (v) => {
  if (!v) return [];
  if (Array.isArray(v)) return v;
  if (typeof v.toArray === 'function') return v.toArray();
  if (typeof v.get === 'function') { const a = []; for (let i = 0; i < v.length; i++) a.push(v.get(i)); return a; }
  return Array.from(v);
};
const hexToRgb = (c) => [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16));
const rgbToHex = (a) => '#' + a.map((v) => Math.round(v).toString(16).padStart(2, '0')).join('');
const mix = (c1, c2, k) => { const a = hexToRgb(c1), b = hexToRgb(c2); return rgbToHex(a.map((v, j) => v + (b[j] - v) * k)); };
const clamp01 = (x) => Math.max(0, Math.min(1, x));
const fmt2 = (v) => v.toLocaleString(LOCALE, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const fmtTime = (t) => new Date(t).toLocaleTimeString(LOCALE, { hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
const fmtDur = (ms) => {
  const m = Math.round(ms / 60000);
  const h = Math.floor(m / 60);
  return h > 0 ? `${h}<small>h</small> ${String(m % 60).padStart(2, '0')}<small>m</small>` : `${m}<small>m</small>`;
};

/* ---------- Data (nulls are skipped) ---------- */
let points = [];
let hasTime = false;
for (const s of (data && data.series) || []) {
  const tf = s.fields.find((f) => f.type === 'time');
  const vf = s.fields.find((f) => f.type === 'number') || s.fields.find((f) => f.type !== 'time');
  if (!vf) continue;
  hasTime = !!tf;
  const ts = tf ? toArr(tf.values) : [];
  toArr(vf.values).forEach((v, i) => {
    if (v === null || v === undefined || v === '') return;
    const n = Number(v);
    if (isNaN(n) || n < 0 || n > 15) return;
    points.push({ t: ts[i] != null ? Number(ts[i]) : i * 60000, v: n });
  });
  break;
}
points.sort((a, b) => a.t - b.t);

/* ---------- Switch (bound once) ---------- */
if (!st.bound) {
  htmlNode.querySelectorAll('.pwr-opt').forEach((btn) => {
    btn.addEventListener('click', () => {
      const m = btn.dataset.mode;
      if (m === st.mode) return;
      st.mode = m;
      try { localStorage.setItem(STORE_KEY, m); } catch (e) {}
      st.drawn = false;
      st.level = null;
      card.classList.remove('is-switching');
      void card.offsetWidth;
      card.classList.add('is-switching');
      if (st.paint) st.paint();
    });
  });
  st.bound = true;
}

if (!points.length) {
  card.dataset.mode = st.mode;
  htmlNode.querySelectorAll('.pwr-opt').forEach((b) => b.classList.toggle('is-active', b.dataset.mode === st.mode));
  $('pwr-value').textContent = '--';
  $('pwr-level').textContent = 'No data in range';
  $('pwr-pill').innerHTML = '';
  card.classList.add('is-stale');
  st.paint = null;
  return;
}

/* ---------- Common calculations ---------- */
const vals = points.map((p) => p.v);
const last = points[points.length - 1];
const cur = last.v;
const vMin = Math.min(...vals);
const vMax = Math.max(...vals);
const vAvg = vals.reduce((a, b) => a + b, 0) / vals.length;
card.classList.toggle('is-stale', hasTime && Date.now() - last.t > STALE_MS);

/* Ripple over the last 30 min (mV) */
const rip = points.filter((p) => p.t >= last.t - RIPPLE_WINDOW_MS).map((p) => p.v);
const rippleMv = rip.length > 1 ? (Math.max(...rip) - Math.min(...rip)) * 1000 : 0;

/* Time with enough voltage to charge */
let chargeMs = 0;
for (let i = 1; i < points.length; i++) {
  const a = points[i - 1], b = points[i];
  const dt = b.t - a.t;
  if (dt > 0 && dt <= GAP_MS && a.v >= SOLAR.chargerOk && b.v >= SOLAR.chargerOk) chargeMs += dt;
}

/* ---------- Animated value (mode independent) ---------- */
const valEl = $('pwr-value');
if (st.num !== cur) {
  const from = st.num ?? 0;
  cancelAnimationFrame(st.raf);
  const t0 = performance.now();
  const dur = 1200;
  const step = (now) => {
    const k = Math.min(1, (now - t0) / dur);
    const e = 1 - Math.pow(1 - k, 3);
    valEl.textContent = fmt2(from + (cur - from) * e);
    if (k < 1) st.raf = requestAnimationFrame(step);
  };
  st.raf = requestAnimationFrame(step);
  st.num = cur;
}

/* ---------- Solar panel cells (built once) ---------- */
const cellsG = $('pwr-cells');
if (!cellsG.children.length) {
  const TL = [20, 52], TR = [110, 46], BR = [124, 96], BL = [28, 102];
  const P = (u, v) => [0, 1].map((k) =>
    TL[k] * (1 - u) * (1 - v) + TR[k] * u * (1 - v) + BR[k] * u * v + BL[k] * (1 - u) * v);
  const cols = 4, rows = 3, g = 0.02;
  let s = '';
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const u0 = c / cols + g, u1 = (c + 1) / cols - g, v0 = r / rows + g * 1.4, v1 = (r + 1) / rows - g * 1.4;
      const pts = [P(u0, v0), P(u1, v0), P(u1, v1), P(u0, v1)].map(([x, y]) => `${x.toFixed(1)},${y.toFixed(1)}`).join(' ');
      s += `<polygon points="${pts}"/>`;
    }
  }
  cellsG.innerHTML = s;
}

/* ---------- Smooth path ---------- */
const smooth = (P) => {
  let d = `M${P[0][0].toFixed(1)},${P[0][1].toFixed(1)}`;
  for (let i = 0; i < P.length - 1; i++) {
    const p0 = P[i - 1] || P[i], p1 = P[i], p2 = P[i + 1], p3 = P[i + 2] || p2;
    const t = 1 / 6;
    const c1x = p1[0] + (p2[0] - p0[0]) * t, c1y = p1[1] + (p2[1] - p0[1]) * t;
    const c2x = p2[0] - (p3[0] - p1[0]) * t, c2y = p2[1] - (p3[1] - p1[1]) * t;
    d += ` C${c1x.toFixed(1)},${c1y.toFixed(1)} ${c2x.toFixed(1)},${c2y.toFixed(1)} ${p2[0].toFixed(1)},${p2[1].toFixed(1)}`;
  }
  return d;
};

/* ---------- Paint (runs on refresh and on mode switch) ---------- */
const paint = () => {
  const mode = st.mode;
  const isSolar = mode === 'solar';
  card.dataset.mode = mode;
  htmlNode.querySelectorAll('.pwr-opt').forEach((b) => b.classList.toggle('is-active', b.dataset.mode === mode));

  const level = (isSolar ? SOLAR_LEVELS : PSU_LEVELS).find((l) => cur < l.max);
  card.style.setProperty('--accent', level.color);
  card.style.setProperty('--accent-hi', mix(level.color, '#ffffff', 0.35));

  /* Level */
  const lvlEl = $('pwr-level');
  if (st.level !== level.label) {
    lvlEl.textContent = level.label;
    lvlEl.classList.remove('pwr-swap');
    void lvlEl.offsetWidth;
    lvlEl.classList.add('pwr-swap');
    st.level = level.label;
  }

  /* Status pill */
  let pill;
  if (isSolar) {
    if (cur >= SOLAR.chargerOk) pill = { cls: 'ok', icon: ICONS.bolt, text: 'Charger active' };
    else if (cur >= SOLAR.chargerMin) pill = { cls: 'warn', icon: ICONS.alert, text: 'At charger limit' };
    else pill = { cls: 'off', icon: ICONS.off, text: `Below ${fmt2(SOLAR.chargerMin)} V minimum` };
  } else {
    if (cur < PSU.offBelow) pill = { cls: 'bad', icon: ICONS.off, text: 'No input' };
    else if (cur >= PSU.specLo && cur <= PSU.specHi) pill = { cls: 'ok', icon: ICONS.check, text: 'Within USB spec' };
    else pill = { cls: 'warn', icon: ICONS.alert, text: 'Out of USB spec' };
  }
  const pillEl = $('pwr-pill');
  pillEl.className = 'pwr-pill pwr-pill--' + pill.cls;
  pillEl.innerHTML = pill.icon + '<span>' + pill.text + '</span>';

  /* Illustrations */
  const sun = clamp01((cur - SOLAR.nightBelow) / (6.5 - SOLAR.nightBelow));
  card.style.setProperty('--sun', sun.toFixed(3));
  card.style.setProperty('--sweep', (9 - 5 * sun).toFixed(1) + 's');
  card.classList.toggle('is-night', isSolar && cur < SOLAR.nightBelow);
  card.classList.toggle('is-off', !isSolar && cur < PSU.offBelow);

  /* Bar */
  const R = isSolar ? SOLAR : PSU;
  const pos = (v) => (clamp01((v - R.min) / (R.max - R.min)) * 100).toFixed(2) + '%';
  if (!st.init) { htmlNode.querySelector('.pwr-fill').getBoundingClientRect(); st.init = true; }
  card.style.setProperty('--pct', pos(cur));
  const tick = $('pwr-tick');
  if (isSolar) {
    card.style.setProperty('--tick', pos(SOLAR.chargerMin));
    card.style.setProperty('--zone-l', pos(SOLAR.chargerOk));
    card.style.setProperty('--zone-w', (100 - parseFloat(pos(SOLAR.chargerOk))).toFixed(2) + '%');
    tick.dataset.label = `${fmt2(SOLAR.chargerMin)} V MIN`;
    $('pwr-bar-label').textContent = 'Panel voltage';
    $('pwr-scale').innerHTML = '<span>0 V</span><span>2.5 V</span><span>5 V</span><span>7.5 V</span>';
  } else {
    card.style.setProperty('--tick', pos(PSU.nominal));
    card.style.setProperty('--zone-l', pos(PSU.specLo));
    card.style.setProperty('--zone-w', (parseFloat(pos(PSU.specHi)) - parseFloat(pos(PSU.specLo))).toFixed(2) + '%');
    tick.dataset.label = `${fmt2(PSU.nominal)} V`;
    $('pwr-bar-label').textContent = 'Input voltage';
    $('pwr-scale').innerHTML = '<span>4.0 V</span><span>4.5 V</span><span>5.0 V</span><span>5.5 V</span><span>6.0 V</span>';
  }
  $('pwr-bar-value').textContent = fmt2(cur) + ' V';

  /* Chart */
  const recent = points.slice(-MAX_POINTS);
  const rv = recent.map((p) => p.v);
  const rMin = Math.min(...rv), rMax = Math.max(...rv);
  const svg = $('pwr-svg');
  const w = Math.max(80, svg.clientWidth || 300);
  const h = Math.max(60, svg.clientHeight || 100);
  svg.setAttribute('viewBox', `0 0 ${w} ${h}`);

  const lo = isSolar ? 0 : Math.min(4.6, rMin - 0.05);
  const hi = isSolar ? Math.max(SOLAR.max, rMax * 1.05) : Math.max(5.4, rMax + 0.05);
  const padX = 4, padY = 8;
  const yOf = (v) => h - padY - ((v - lo) / (hi - lo)) * (h - padY * 2);
  const xy = rv.map((v, i) => [
    rv.length === 1 ? w / 2 : padX + (i * (w - padX * 2)) / (rv.length - 1),
    yOf(v)
  ]);

  const band = $('pwr-ref-band'), l1 = $('pwr-ref-l1'), l2 = $('pwr-ref-l2'), lbl = $('pwr-ref-label');
  const setLine = (el, y, show) => {
    el.setAttribute('x1', 0); el.setAttribute('x2', w);
    el.setAttribute('y1', y.toFixed(1)); el.setAttribute('y2', y.toFixed(1));
    el.style.display = show ? '' : 'none';
  };
  if (isSolar) {
    const y = yOf(SOLAR.chargerMin);
    band.style.display = 'none';
    setLine(l1, y, true);
    setLine(l2, y, false);
    lbl.textContent = 'CHARGER MIN';
    lbl.setAttribute('x', (w - 2).toFixed(1));
    lbl.setAttribute('y', (y - 4).toFixed(1));
    $('pwr-chart-title').textContent = 'Panel voltage history';
  } else {
    const yTop = yOf(PSU.specHi), yBot = yOf(PSU.specLo);
    band.style.display = '';
    band.setAttribute('x', 0);
    band.setAttribute('y', yTop.toFixed(1));
    band.setAttribute('width', w);
    band.setAttribute('height', Math.max(0, yBot - yTop).toFixed(1));
    setLine(l1, yTop, true);
    setLine(l2, yBot, true);
    lbl.textContent = 'USB SPEC';
    lbl.setAttribute('x', (w - 2).toFixed(1));
    lbl.setAttribute('y', (yTop - 4).toFixed(1));
    $('pwr-chart-title').textContent = 'Input voltage history';
  }
  $('pwr-range').textContent = `${fmt2(rMin)} – ${fmt2(rMax)} V`;

  const lineD = smooth(xy);
  const line = $('pwr-line');
  const area = $('pwr-area');
  line.setAttribute('d', lineD);
  area.setAttribute('d', `${lineD} L${xy[xy.length - 1][0].toFixed(1)},${h} L${xy[0][0].toFixed(1)},${h} Z`);
  const [lx, ly] = xy[xy.length - 1];
  ['pwr-dot', 'pwr-ring'].forEach((id) => {
    const c = $(id);
    c.setAttribute('cx', lx.toFixed(1));
    c.setAttribute('cy', ly.toFixed(1));
  });
  if (!st.drawn) {
    const len = line.getTotalLength();
    line.style.transition = 'none';
    line.style.strokeDasharray = len;
    line.style.strokeDashoffset = len;
    line.getBoundingClientRect();
    line.style.transition = 'stroke-dashoffset 1.6s cubic-bezier(0.4, 0, 0.2, 1)';
    line.style.strokeDashoffset = '0';
    setTimeout(() => {
      line.style.transition = '';
      line.style.strokeDasharray = 'none';
    }, 1700);
    st.drawn = true;
  }
  area.classList.add('is-visible');

  /* Stats */
  const updated = hasTime ? fmtTime(last.t) : '--';
  const stats = isSolar
    ? [
        ['Peak', fmt2(vMax) + '<small>V</small>'],
        ['Avg', fmt2(vAvg) + '<small>V</small>'],
        ['Charge window', hasTime ? fmtDur(chargeMs) : '--'],
        ['Updated', updated]
      ]
    : [
        ['Min', fmt2(vMin) + '<small>V</small>'],
        ['Max', fmt2(vMax) + '<small>V</small>'],
        ['Ripple', Math.round(rippleMv) + '<small>mV</small>'],
        ['Updated', updated]
      ];
  stats.forEach(([label, value], i) => {
    $(`pwr-s${i + 1}-l`).textContent = label;
    $(`pwr-s${i + 1}-v`).innerHTML = value;
  });
};

st.paint = paint;
paint();
